:root {
  --blue: #23c8ff;
  --blue-deep: #066cff;
  --orange: #ff7a18;
  --orange-deep: #ff3c00;
  --ink: #050912;
  --panel: rgba(7, 15, 28, 0.7);
  --line: rgba(150, 220, 255, 0.18);
  --white: #eaf6ff;
  --muted: #8ba6bd;
  --font-display: 'Russo One', 'Arial Black', Impact, sans-serif;
  --font-ui: 'Rajdhani', 'Arial Narrow', system-ui, sans-serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  height: 100%;
  background: var(--ink);
  color: var(--white);
  font-family: var(--font-ui);
  overflow: hidden;
  overscroll-behavior: none;
}
body { -webkit-tap-highlight-color: transparent; }
button { font-family: inherit; color: inherit; cursor: pointer; }
#app { position: fixed; inset: 0; overflow: hidden; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; outline: none; }
.hidden { display: none !important; }

/* ---------- screen effects ---------- */
.screen-fx { position: absolute; inset: 0; pointer-events: none; z-index: 3; overflow: hidden; }
.vignette {
  position: absolute; inset: 0;
  background:
    radial-gradient(120% 90% at 50% 45%, transparent 48%, rgba(0, 2, 8, 0.52) 100%),
    linear-gradient(180deg, rgba(2, 7, 15, 0.34), transparent 22%, transparent 72%, rgba(1, 4, 10, 0.55));
  mix-blend-mode: multiply;
}
.scanlines {
  position: absolute; inset: 0; opacity: 0.16;
  background: repeating-linear-gradient(0deg, rgba(140, 230, 255, 0.11) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
}
.flash { position: absolute; inset: 0; background: #fff; opacity: 0; transition: opacity 0.55s ease-out; }
.flash.on { opacity: 0.65; transition: opacity 0.02s; }

/* ---------- generic UI ---------- */
.screen { position: absolute; inset: 0; z-index: 20; }
.icon-btn {
  width: 42px; height: 42px; border-radius: 50%;
  border: 1px solid rgba(160, 225, 255, 0.24);
  background: rgba(5, 13, 25, 0.55);
  display: grid; place-items: center; padding: 0;
  backdrop-filter: blur(8px);
  transition: border-color .2s, background .2s, transform .2s;
}
.icon-btn:hover { border-color: var(--blue); background: rgba(20, 110, 160, 0.3); transform: translateY(-1px); }
.icon-btn svg { width: 21px; height: 21px; fill: #d8f2ff; }
.icon-btn .wave { opacity: 1; transition: opacity .2s; }
.icon-btn.muted .wave { opacity: 0; }
.icon-btn.muted { color: #5d7183; }
.cam-btn.on { border-color: var(--blue); box-shadow: 0 0 18px rgba(20, 200, 255, .35), inset 0 0 12px rgba(20, 200, 255, .2); }

.ghost-btn {
  border: 1px solid rgba(155, 220, 255, 0.26);
  background: linear-gradient(180deg, rgba(24, 54, 82, .4), rgba(4, 10, 20, .55));
  padding: 13px 26px; border-radius: 3px;
  font-family: var(--font-display); font-size: 14px; letter-spacing: 1.4px;
  color: #cfe9f8; backdrop-filter: blur(8px);
  transition: all .18s ease;
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}
.ghost-btn:hover { border-color: var(--blue); color: #fff; box-shadow: 0 0 24px rgba(20, 190, 255, .22); background: rgba(18, 68, 100, .5); }
.ghost-btn.small { padding: 9px 18px; font-size: 12px; }
.play-btn {
  position: relative; display: inline-flex; align-items: center; gap: 14px;
  border: 0; padding: 17px 34px;
  background: linear-gradient(105deg, #10bfe7, #0878e8 58%, #0751c8);
  color: #02111e;
  clip-path: polygon(13px 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%, 0 13px);
  box-shadow: 0 8px 30px rgba(0, 160, 255, .32), inset 0 1px 0 rgba(255,255,255,.4);
  overflow: hidden; transition: transform .16s ease, filter .16s;
}
.play-btn:hover { transform: translateY(-2px); filter: brightness(1.13); }
.play-btn:active { transform: translateY(0) scale(.985); }
.play-btn .play-icon {
  display: grid; place-items: center; width: 42px; height: 42px; border-radius: 50%;
  background: rgba(2, 16, 30, .82); color: #4ee6ff; font-size: 17px; padding-left: 3px;
  box-shadow: inset 0 0 0 1px rgba(110, 240, 255, .5);
}
.play-text { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; text-align: left; }
.play-text b { font-family: var(--font-display); font-size: 20px; letter-spacing: 1.2px; }
.play-text small { font-family: var(--font-ui); font-weight: 700; font-size: 11px; letter-spacing: 2px; opacity: .66; }
.play-btn.compact { padding: 12px 24px; }
.play-btn.compact .play-icon { width: 32px; height: 32px; font-size: 14px; }
.play-btn.compact .play-text b { font-size: 16px; }
.play-glow { position: absolute; top: 0; bottom: 0; width: 40%; left: -50%; background: linear-gradient(90deg, transparent, rgba(255,255,255,.6), transparent); transform: skewX(-20deg); animation: shine 3.6s ease-in-out infinite; }
@keyframes shine { 0%, 55% { left: -60%; } 80%, 100% { left: 120%; } }

/* ---------- loading ---------- */
.loading { position: absolute; inset: 0; z-index: 50; display: grid; place-content: center; gap: 18px; justify-items: center; background: #050912; transition: opacity .5s; }
.loading.done { opacity: 0; pointer-events: none; }
.loading-mark { width: 54px; height: 54px; border: 2px solid rgba(40, 210, 255, .18); border-top-color: var(--blue); border-radius: 50%; animation: spin 1s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.loading-text { font-family: var(--font-display); font-size: 11px; letter-spacing: 4px; color: #74d9f6; }

/* ===================== HUD ===================== */
.hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.hud button { pointer-events: auto; }
.hud-top { position: absolute; top: max(16px, env(safe-area-inset-top)); left: 0; right: 0; display: flex; justify-content: center; align-items: flex-start; padding: 0 18px; }
.minimap-panel {
  position: absolute; left: max(18px, env(safe-area-inset-left)); top: 0;
  width: 190px; padding: 8px 8px 6px;
  background: linear-gradient(160deg, rgba(6, 18, 34, .82), rgba(3, 8, 16, .58));
  border: 1px solid rgba(100, 200, 255, .18);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
  backdrop-filter: blur(8px);
}
#minimap { width: 100%; height: auto; display: block; }
.minimap-label { font-family: var(--font-display); font-size: 8px; letter-spacing: 3.4px; color: #5bb3d2; padding: 3px 1px 0; display: flex; align-items: center; gap: 6px; }
.minimap-label:before { content: ''; width: 5px; height: 5px; background: #ff9f35; border-radius: 50%; box-shadow: 0 0 6px #ff9f35; }

.scoreboard {
  display: flex; align-items: stretch;
  background: linear-gradient(180deg, rgba(9, 22, 42, .89), rgba(3, 9, 18, .8));
  border: 1px solid rgba(110, 210, 255, .18);
  box-shadow: 0 12px 40px rgba(0, 0, 0, .4), inset 0 1px 0 rgba(140, 230, 255, .16);
  clip-path: polygon(14px 0, calc(100% - 14px) 0, 100% 50%, calc(100% - 14px) 100%, 14px 100%, 0 50%);
  padding: 0 26px;
  min-width: 460px;
  backdrop-filter: blur(10px);
}
.team { display: flex; align-items: center; gap: 12px; padding: 9px 6px; min-width: 142px; }
.blue-team { justify-content: flex-end; text-align: right; }
.orange-team { justify-content: flex-start; }
.team-badge {
  width: 38px; height: 38px; display: grid; place-items: center;
  clip-path: polygon(50% 0, 100% 26%, 100% 74%, 50% 100%, 0 74%, 0 26%);
  font-family: var(--font-display); font-size: 18px;
}
.blue-team .team-badge { background: linear-gradient(150deg, #63ebff, #0766ff); color: #021223; box-shadow: 0 0 22px rgba(30, 190, 255, .6); }
.orange-team .team-badge { background: linear-gradient(150deg, #ffc65c, #ff4b00); color: #1d0700; box-shadow: 0 0 22px rgba(255, 115, 20, .55); }
.team-meta { display: flex; flex-direction: column; line-height: 1; }
.team-name { font-family: var(--font-display); font-size: 10px; letter-spacing: 2.2px; }
.blue-team .team-name { color: var(--blue); }
.orange-team .team-name { color: var(--orange); }
.team-tag { font-size: 9px; font-weight: 700; letter-spacing: 2px; color: #5f7b91; margin-top: 3px; }
.team-score { font-family: var(--font-display); font-size: 30px; min-width: 36px; text-align: center; text-shadow: 0 0 18px currentColor; }
.blue-team .team-score { color: #8deaff; }
.orange-team .team-score { color: #ffb063; }
.match-clock { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 8px 20px 7px; border-left: 1px solid var(--line); border-right: 1px solid var(--line); min-width: 118px; }
.clock { font-family: var(--font-display); font-size: 25px; letter-spacing: 2px; color: #fff; }
.clock.urgent { color: #ff6138; animation: pulse-clock 1s infinite; }
@keyframes pulse-clock { 50% { opacity: .55; } }
.clock-label { font-size: 8px; font-weight: 700; letter-spacing: 3px; color: #66849b; margin-top: 2px; }
.clock-bar { width: 70px; height: 2px; margin-top: 5px; background: rgba(120, 200, 230, .16); overflow: hidden; }
.clock-bar i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #17c8ff, #ff8a24); box-shadow: 0 0 8px #19baff; transition: width .6s linear; }
.hud-right { position: absolute; right: max(18px, env(safe-area-inset-right)); top: 0; display: flex; gap: 8px; }

.boost-hud {
  position: absolute; right: max(26px, env(safe-area-inset-right)); bottom: max(26px, env(safe-area-inset-bottom));
  display: flex; align-items: flex-end; gap: 18px;
}
.boost-ring-wrap { position: relative; width: 108px; height: 108px; filter: drop-shadow(0 6px 18px rgba(0,0,0,.45)); }
.boost-ring { width: 100%; height: 100%; transform: rotate(-90deg); }
.boost-track { fill: rgba(4, 12, 22, .62); stroke: rgba(110, 190, 220, .18); stroke-width: 7; }
.boost-arc { fill: none; stroke: #ffb31f; stroke-width: 7; stroke-linecap: round; stroke-dasharray: 264; stroke-dashoffset: 176; transition: stroke-dashoffset .12s linear, stroke .2s; filter: drop-shadow(0 0 5px #ffae00); }
.boost-core { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
