.boost-core span { font-size: 8px; font-weight: 700; letter-spacing: 2.5px; color: #b08b52; margin-top: 2px; }
.boost-hud.low .boost-arc { stroke: #ff4d2b; filter: drop-shadow(0 0 6px #ff3b1a); }
.speed-wrap { display: flex; flex-direction: column; align-items: flex-end; padding-bottom: 8px; min-width: 105px; }
.speed { font-family: var(--font-display); font-size: 38px; line-height: .9; color: #e9f8ff; text-shadow: 0 0 18px rgba(50, 200, 255, .35); letter-spacing: 1px; }
.speed-unit { font-size: 9px; font-weight: 700; letter-spacing: 3px; color: #6e8ba2; margin-top: 2px; }
