.countdown { position: absolute; inset: 0; display: grid; place-items: center; }
.countdown span {
  font-family: var(--font-display); font-size: clamp(110px, 20vw, 240px); line-height: 1;
  color: #fff; text-shadow: 0 0 40px rgba(40, 210, 255, .9), 0 0 120px rgba(0, 120, 255, .6);
  animation: countpop .9s cubic-bezier(.2,.9,.3,1);
}
.countdown.go span { color: #ffcf4a; text-shadow: 0 0 50px rgba(255, 160, 0, .95), 0 0 130px rgba(255, 80, 0, .55); font-size: clamp(90px, 16vw, 190px); }
@keyframes countpop { 0% { transform: scale(1.7); opacity: 0; filter: blur(8px); } 30% { transform: scale(1); opacity: 1; filter: blur(0); } 100% { transform: scale(.9); opacity: 0; } }

.announce { position: absolute; left: 0; right: 0; top: 28%; display: flex; flex-direction: column; align-items: center; pointer-events: none; }
.announce-kicker { font-family: var(--font-display); font-size: 12px; letter-spacing: 8px; color: #aee9ff; margin-bottom: 8px; }
.announce-main {
  font-family: var(--font-display); font-size: clamp(46px, 9vw, 112px); line-height: .9; letter-spacing: 3px;
  color: #fff; text-shadow: 0 0 42px currentColor, 0 12px 50px rgba(0,0,0,.6);
  animation: announceIn .5s cubic-bezier(.15,.9,.3,1) both;
}
.announce-sub { font-size: 14px; font-weight: 700; letter-spacing: 6px; color: #b9d6e8; margin-top: 14px; }
.announce.blue .announce-main { color: var(--blue); }
.announce.orange .announce-main { color: var(--orange); }
.announce.gold .announce-main { color: #ffd24a; }
@keyframes announceIn { from { transform: translateY(30px) scale(1.12); opacity: 0; filter: blur(10px); } to { transform: none; opacity: 1; filter: blur(0); } }

.hint {
  position: absolute; left: 50%; bottom: max(20px, env(safe-area-inset-bottom)); transform: translateX(-50%);
  font-size: 10px; font-weight: 700; letter-spacing: 1.7px; color: #8ba9bf;
