}
.hint .sep { display: inline-block; width: 1px; height: 10px; background: rgba(150, 210, 240, .2); margin: 0 9px; vertical-align: middle; }
.toast {
  position: absolute; left: 50%; bottom: 18%; transform: translateX(-50%) translateY(10px);
