/**
 * Unified input: keyboard, gamepad and multi-touch.
 * Produces a single control snapshot for the player car each frame.
 */
export class Input {
  constructor() {
    this.keys = new Set();
    this.pressed = new Set();
    this.released = new Set();
    this.touch = { x: 0, y: 0, jump: false, boost: false, active: false };
    this.padPrev = new Array(16).fill(false);
    this.gamepadIndex = null;
    this.touchEnabled = false;
    this._bindKeyboard();
  }

  _bindKeyboard() {
    const blocked = new Set([
      'Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
      'KeyW', 'KeyA', 'KeyS', 'KeyD', 'ShiftLeft', 'ShiftRight', 'Escape',
    ]);
    window.addEventListener('keydown', (e) => {
      if (blocked.has(e.code)) e.preventDefault();
      if (e.repeat) return;
      this.keys.add(e.code);
      const action = this._keyAction(e.code);
      if (action) this.pressed.add(action);
    }, { passive: false });
    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
      const action = this._keyAction(e.code);
      if (action) this.released.add(action);
    });
    window.addEventListener('blur', () => this.keys.clear());
  }

  _keyAction(code) {
    switch (code) {
      case 'Space': return 'jump';
      case 'ShiftLeft':
      case 'ShiftRight': return 'boost';
      case 'KeyC': return 'ballcam';
      case 'KeyM': return 'sound';
      case 'Escape':
      case 'KeyP': return 'pause';
      default: return null;
    }
  }

  bindTouchControls({ stickZone, knob, jumpBtn, boostBtn }) {
    this.touchEnabled = true;
    const maxR = () => Math.min(stickZone.clientWidth, stickZone.clientHeight) * 0.34;
    let pointerId = null;

    const updateStick = (e) => {
      const rect = stickZone.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      let dx = e.clientX - cx;
      let dy = e.clientY - cy;
      const r = maxR();
      const len = Math.hypot(dx, dy);
      if (len > r) { dx = dx / len * r; dy = dy / len * r; }
      this.touch.x = dx / r;
      this.touch.y = dy / r;
      this.touch.active = true;
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
    };
    const resetStick = () => {
      pointerId = null;
      this.touch.x = 0;
      this.touch.y = 0;
      this.touch.active = false;
      knob.style.transform = '';
    };

    stickZone.addEventListener('pointerdown', (e) => {
      pointerId = e.pointerId;
      stickZone.setPointerCapture(e.pointerId);
      updateStick(e);
      e.preventDefault();
    }, { passive: false });
    stickZone.addEventListener('pointermove', (e) => {
      if (e.pointerId !== pointerId) return;
      updateStick(e);
      e.preventDefault();
    }, { passive: false });
    stickZone.addEventListener('pointerup', resetStick);
    stickZone.addEventListener('pointercancel', resetStick);
    stickZone.addEventListener('lostpointercapture', resetStick);

    const holdButton = (btn, prop, action) => {
      const press = (e) => {
        btn.classList.add('held');
        this.touch[prop] = true;
        this.touch.active = true;
        if (action) this.pressed.add(action);
        e.preventDefault();
      };
      const release = () => {
        btn.classList.remove('held');
        this.touch[prop] = false;
      };
      btn.addEventListener('pointerdown', press, { passive: false });
      btn.addEventListener('pointerup', release);
      btn.addEventListener('pointercancel', release);
      btn.addEventListener('pointerleave', (e) => { if (e.buttons === 0) release(); });
    };
    holdButton(jumpBtn, 'jump', 'jump');
    holdButton(boostBtn, 'boost', null);
  }

  _pollGamepad() {
    const pads = navigator.getGamepads ? navigator.getGamepads() : [];
    let pad = null;
    for (const p of pads) {
      if (p && p.connected) { pad = p; break; }
    }
    if (!pad) { this.padPrev.fill(false); return; }
    const pressedNow = (i) => !!(pad.buttons[i] && pad.buttons[i].pressed);
    const edges = { 0: 'jump', 2: 'ballcam', 9: 'pause' };
    for (const [index, action] of Object.entries(edges)) {
      const now = pressedNow(Number(index));
      if (now && !this.padPrev[index]) this.pressed.add(action);
      this.padPrev[index] = now;
    }
    this._pad = {
      steer: Math.abs(pad.axes[0] || 0) > 0.14 ? pad.axes[0] : 0,
      throttle: Math.abs(pad.axes[1] || 0) > 0.14 ? -pad.axes[1] : 0,
      boost: pressedNow(1) || pressedNow(7) || (pad.buttons[6] && pad.buttons[6].value > 0.2),
      jump: pressedNow(0),
    };
  }

  poll() {
    this._pollGamepad();
    let throttle = 0;
    let steer = 0;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) throttle += 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) throttle -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) steer += 1;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) steer -= 1;

    let jump = this.keys.has('Space');
    let boost = this.keys.has('ShiftLeft') || this.keys.has('ShiftRight');
    let roll = 0;
    if (this.keys.has('KeyE')) roll += 1;
    if (this.keys.has('KeyQ')) roll -= 1;

    if (this._pad) {
      if (Math.abs(this._pad.steer) > 0) steer = this._pad.steer;
      if (Math.abs(this._pad.throttle) > 0) throttle = this._pad.throttle;
      boost = boost || this._pad.boost;
      jump = jump || this._pad.jump;
    }
    if (this.touch.active) {
      steer += this.touch.x;
      throttle -= this.touch.y;
      jump = jump || this.touch.jump;
      boost = boost || this.touch.boost;
    }

    steer = Math.max(-1, Math.min(1, steer));
    throttle = Math.max(-1, Math.min(1, throttle));
    return {
      throttle,
      steer,
      jump,
      jumpPressed: this.pressed.has('jump'),
      boost,
      roll,
    };
  }

  wasPressed(action) { return this.pressed.has(action); }

  endFrame() {
    this.pressed.clear();
    this.released.clear();
  }

  vibrate(ms = 40) {
    if (navigator.vibrate) navigator.vibrate(ms);
  }
}

/** Procedural WebAudio soundscape — no external assets required. */
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.ready = false;
    this.scene = 'menu';
    this.cheer = 0;
    this.boostEnv = 0;
    this._lastHit = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = this.ctx = new AC();
    this.ready = true;
    const master = this.master = ctx.createGain();
    master.gain.value = this.enabled ? 0.62 : 0;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 22;
    comp.ratio.value = 5;
    comp.attack.value = 0.005;
    comp.release.value = 0.22;
    master.connect(comp).connect(ctx.destination);

    this.noiseBuffer = this._makeNoise(2.4);

    // ---- engine ----
    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0.0001;
    const engineFilter = this.engineFilter = ctx.createBiquadFilter();
    engineFilter.type = 'lowpass';
    engineFilter.frequency.value = 340;
    engineFilter.Q.value = 5.5;
    this.osc1 = ctx.createOscillator();
    this.osc1.type = 'sawtooth';
    this.osc1.frequency.value = 44;
    this.osc2 = ctx.createOscillator();
    this.osc2.type = 'square';
    this.osc2.frequency.value = 67;
    const g2 = ctx.createGain();
    g2.gain.value = 0.28;
    this.osc1.connect(engineFilter);
    this.osc2.connect(g2).connect(engineFilter);
    engineFilter.connect(this.engineGain).connect(master);
    this.osc1.start();
    this.osc2.start();

    // ---- wind ----
    const wind = ctx.createBufferSource();
    wind.buffer = this.noiseBuffer;
    wind.loop = true;
    const windFilter = this.windFilter = ctx.createBiquadFilter();
    windFilter.type = 'bandpass';
    windFilter.frequency.value = 800;
    windFilter.Q.value = 0.6;
    this.windGain = ctx.createGain();
    this.windGain.gain.value = 0.0001;
    wind.connect(windFilter).connect(this.windGain).connect(master);
    wind.start();

    // ---- boost ----
    const boost = ctx.createBufferSource();
    boost.buffer = this.noiseBuffer;
    boost.loop = true;
    const boostFilter = this.boostFilter = ctx.createBiquadFilter();
    boostFilter.type = 'bandpass';
    boostFilter.frequency.value = 1500;
    boostFilter.Q.value = 0.9;
    this.boostGain = ctx.createGain();
    this.boostGain.gain.value = 0.0001;
    boost.connect(boostFilter).connect(this.boostGain).connect(master);
    boost.start();

    // ---- crowd ----
    const crowd = ctx.createBufferSource();
    crowd.buffer = this.noiseBuffer;
    crowd.loop = true;
    const crowdFilter = this.crowdFilter = ctx.createBiquadFilter();
    crowdFilter.type = 'lowpass';
    crowdFilter.frequency.value = 620;
    this.crowdGain = ctx.createGain();
    this.crowdGain.gain.value = 0.0001;
    crowd.connect(crowdFilter).connect(this.crowdGain).connect(master);
    crowd.start();

    // ---- ambient pad ----
    this.musicGain = ctx.createGain();
    this.musicGain.gain.value = 0.0001;
    const musicFilter = ctx.createBiquadFilter();
    musicFilter.type = 'lowpass';
    musicFilter.frequency.value = 900;
    const notes = [55, 82.41, 110, 164.81];
    this.padOscs = notes.map((f, i) => {
      const o = ctx.createOscillator();
      o.type = i % 2 ? 'triangle' : 'sine';
      o.frequency.value = f;
      o.detune.value = (i - 1.5) * 3;
      const g = ctx.createGain();
      g.gain.value = i === 0 ? 0.055 : 0.028;
      o.connect(g).connect(musicFilter);
      o.start();
      return o;
    });
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.055;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 240;
    lfo.connect(lfoGain).connect(musicFilter.frequency);
    lfo.start();
    musicFilter.connect(this.musicGain).connect(master);

    this.setScene('menu');
  }

  _makeNoise(seconds) {
    const ctx = this.ctx;
    const buffer = ctx.createBuffer(2, Math.floor(ctx.sampleRate * seconds), ctx.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const data = buffer.getChannelData(ch);
      let last = 0;
      for (let i = 0; i < data.length; i++) {
        const white = Math.random() * 2 - 1;
        last = last * 0.86 + white * 0.14;
        data[i] = last * 1.9;
      }
    }
    return buffer;
  }

  setEnabled(on) {
    this.enabled = on;
    if (!this.ctx) return;
    this.master.gain.cancelScheduledValues(this.ctx.currentTime);
    this.master.gain.linearRampToValueAtTime(on ? 0.62 : 0.0001, this.ctx.currentTime + 0.15);
  }

  setScene(scene) {
    this.scene = scene;
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const music = scene === 'menu' ? 0.16 : 0.055;
    this.musicGain.gain.cancelScheduledValues(t);
    this.musicGain.gain.linearRampToValueAtTime(music, t + 1.2);
    const crowd = scene === 'menu' ? 0.02 : 0.035;
    this.crowdGain.gain.linearRampToValueAtTime(crowd, t + 0.8);
  }

  update(dt, { speed = 0, throttle = 0, boosting = false, grounded = true, paused = false }) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const sp = Math.min(1, speed / 55);
    const target = paused ? 0.0001 : 0.055 + sp * 0.11 + (grounded ? Math.abs(throttle) * 0.035 : 0.02);
    this.engineGain.gain.setTargetAtTime(target, t, 0.08);
    const freq = 40 + sp * 92 + Math.abs(throttle) * (grounded ? 15 : 4);
    this.osc1.frequency.setTargetAtTime(freq, t, 0.1);
    this.osc2.frequency.setTargetAtTime(freq * 1.505, t, 0.12);
    this.engineFilter.frequency.setTargetAtTime(260 + sp * 900 + (boosting ? 260 : 0), t, 0.1);

    this.windGain.gain.setTargetAtTime(paused ? 0.0001 : sp * sp * 0.1, t, 0.16);
    this.windFilter.frequency.setTargetAtTime(500 + sp * 1800, t, 0.2);

    this.boostEnv += ((boosting && !paused ? 1 : 0) - this.boostEnv) * Math.min(1, dt * 15);
    this.boostGain.gain.setTargetAtTime(0.004 + this.boostEnv * 0.16, t, 0.04);
    this.boostFilter.frequency.setTargetAtTime(1200 + this.boostEnv * 1600, t, 0.05);

    this.cheer = Math.max(0, this.cheer - dt * 0.42);
    const crowd = paused ? 0.0001 : (this.scene === 'menu' ? 0.02 : 0.03) + this.cheer * 0.24;
    this.crowdGain.gain.setTargetAtTime(crowd, t, 0.14);
    this.crowdFilter.frequency.setTargetAtTime(500 + this.cheer * 900, t, 0.2);
  }

  _env(gain, t, attack, decay, peak = 1) {
    gain.gain.cancelScheduledValues(t);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), t + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + attack + decay);
  }

  hit(strength = 1, pitch = 1) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    if (now - this._lastHit < 0.035) return;
    this._lastHit = now;
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 700 + strength * 2200;
    const g = ctx.createGain();
    this._env(g, now, 0.005, 0.16, Math.min(0.55, 0.1 + strength * 0.3));
    src.connect(filter).connect(g).connect(this.master);
    src.start(now);
    src.stop(now + 0.22);

    const o = ctx.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(140 * pitch + strength * 80, now);
    o.frequency.exponentialRampToValueAtTime(45, now + 0.16);
    const og = ctx.createGain();
    this._env(og, now, 0.004, 0.2, Math.min(0.45, 0.08 + strength * 0.24));
    o.connect(og).connect(this.master);
    o.start(now);
    o.stop(now + 0.25);
  }

  jump() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    o.type = 'triangle';
    o.frequency.setValueAtTime(160, t);
    o.frequency.exponentialRampToValueAtTime(390, t + 0.12);
    const g = this.ctx.createGain();
    this._env(g, t, 0.005, 0.15, 0.16);
    o.connect(g).connect(this.master);
    o.start(t); o.stop(t + 0.2);
  }

  boostPad(big = false) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    [0, 0.06].forEach((d, i) => {
      const o = this.ctx.createOscillator();
      o.type = 'sine';
      o.frequency.setValueAtTime(big ? 520 + i * 160 : 780 + i * 220, t + d);
      o.frequency.exponentialRampToValueAtTime(big ? 980 + i * 220 : 1200 + i * 260, t + d + 0.1);
      const g = this.ctx.createGain();
      this._env(g, t + d, 0.005, 0.12, big ? 0.17 : 0.09);
      o.connect(g).connect(this.master);
      o.start(t + d); o.stop(t + d + 0.18);
    });
  }

  beep(high = false) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    o.type = 'square';
    o.frequency.value = high ? 880 : 620;
    const g = this.ctx.createGain();
    this._env(g, t, 0.004, high ? 0.37 : 0.12, 0.09);
    o.connect(g).connect(this.master);
    o.start(t); o.stop(t + 0.45);
  }

  goal() {
    if (!this.ready) return;
    this.cheer = 1;
    const t = this.ctx.currentTime;
    // stadium horn
    [0, 0.02].forEach((d, i) => {
      const o = this.ctx.createOscillator();
      o.type = 'sawtooth';
      o.frequency.setValueAtTime(146 + i * 4, t + d);
      o.frequency.exponentialRampToValueAtTime(116, t + d + 0.75);
      const f = this.ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.value = 900;
      const g = this.ctx.createGain();
      this._env(g, t + d, 0.04, 1.35, 0.19);
      o.connect(f).connect(g).connect(this.master);
      o.start(t + d); o.stop(t + d + 1.5);
    });
    // impact boom
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.value = 420;
    const g = this.ctx.createGain();
    this._env(g, t, 0.01, 0.85, 0.36);
    src.connect(f).connect(g).connect(this.master);
    src.start(t); src.stop(t + 1);
  }

  whistle() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    for (let i = 0; i < 2; i++) {
      const o = this.ctx.createOscillator();
      o.type = 'sine';
      o.frequency.setValueAtTime(1900 + i * 6, t + i * 0.18);
      o.frequency.linearRampToValueAtTime(2050, t + i * 0.18 + 0.22);
      const g = this.ctx.createGain();
      this._env(g, t + i * 0.18, 0.01, 0.22, 0.07);
      o.connect(g).connect(this.master);
      o.start(t + i * 0.18); o.stop(t + i * 0.18 + 0.35);
    }
  }

  click() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(760, t);
    const g = this.ctx.createGain();
    this._env(g, t, 0.003, 0.07, 0.06);
    o.connect(g).connect(this.master);
    o.start(t); o.stop(t + 0.1);
  }
}

import * as THREE from 'three';

export const ARENA = {
  length: 120,
  width: 80,
  halfLength: 60,
  halfWidth: 40,
  ceiling: 30,
  goalWidth: 26,
  goalHeight: 12,
  goalDepth: 9,
  ballRadius: 2.1,
  carBaseY: 0.82,
};

const C = {
  blue: 0x20c8ff,
  blueDeep: 0x075cff,
  orange: 0xff7a18,
  orangeDeep: 0xff3c00,
  ice: 0xc9f4ff,
  steel: 0x16202e,
  dark: 0x050b14,
};

function canvasTexture(w, h, draw) {
  const cv = document.createElement('canvas');
  cv.width = w; cv.height = h;
  const ctx = cv.getContext('2d');
  draw(ctx, w, h);
  const tex = new THREE.CanvasTexture(cv);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return tex;
}

function neonMaterial(hex, intensity = 1.8, opacity = 1) {
  const c = new THREE.Color(hex).multiplyScalar(intensity);
  return new THREE.MeshBasicMaterial({ color: c, toneMapped: false, transparent: opacity < 1, opacity });
}

export function createEnvironment(renderer) {
  const cv = document.createElement('canvas');
  cv.width = 1024; cv.height = 512;
  const ctx = cv.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 0, 512);
  g.addColorStop(0, '#0b1a33');
  g.addColorStop(0.45, '#0a2030');
  g.addColorStop(0.55, '#0c101a');
  g.addColorStop(1, '#030609');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 1024, 512);
  // glowing arena light strips
  const colors = ['#1ac8ff', '#ff7a18', '#7fe9ff', '#ffffff'];
  for (let i = 0; i < 14; i++) {
    const x = (i * 83 + 40) % 1024;
    const y = 220 + Math.sin(i * 1.7) * 60;
    const rg = ctx.createRadialGradient(x, y, 2, x, y, 90);
    rg.addColorStop(0, colors[i % colors.length]);
    rg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = rg;
    ctx.fillRect(x - 90, y - 90, 180, 180);
  }
  const tex = new THREE.CanvasTexture(cv);
  tex.mapping = THREE.EquirectangularReflectionMapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  const pmrem = new THREE.PMREMGenerator(renderer);
  pmrem.compileEquirectangularShader();
  const env = pmrem.fromEquirectangular(tex).texture;
  tex.dispose();
  pmrem.dispose();
  return env;
}

export class Arena {
  constructor(scene, renderer) {
    this.scene = scene;
    this.renderer = renderer;
    this.group = new THREE.Group();
    this.group.name = 'arena';
    scene.add(this.group);

    this.pads = [];
    this.flashes = [];
    this.time = 0;
    this.screenState = { blue: 0, orange: 0, clock: '3:00', label: 'REGULATION' };

    this._buildSky();
    this._buildLights();
    this._buildField();
    this._buildWalls();
    this._buildGoals();
    this._buildStands();
    this._buildCrowd();
    this._buildScreens();
    this._buildBoostPads();
    this._buildAtmosphere();
  }

  _buildSky() {
    const geo = new THREE.SphereGeometry(240, 40, 24);
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {},
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        varying vec3 vDir;
        float hash(vec3 p) {
          p = fract(p * 0.3183099 + vec3(0.1, 0.2, 0.3));
          p *= 17.0;
          return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
        }
        void main() {
          float h = clamp(vDir.y * 0.85 + 0.18, 0.0, 1.0);
          vec3 low = vec3(0.035, 0.10, 0.15);
          vec3 mid = vec3(0.012, 0.035, 0.075);
          vec3 top = vec3(0.004, 0.008, 0.022);
          vec3 col = mix(low, mid, smoothstep(0.0, 0.32, h));
          col = mix(col, top, smoothstep(0.30, 0.95, h));
          float glow = pow(max(0.0, 1.0 - abs(vDir.y + 0.02) * 7.0), 3.0);
          col += vec3(0.02, 0.10, 0.16) * glow;
          // sparse stars
          vec2 sp = floor(vDir.xz * 90.0 + vDir.y * 40.0);
          float s = hash(vec3(sp, floor(vDir.y * 90.0)));
          float star = step(0.9975, s) * smoothstep(0.12, 0.5, vDir.y);
          col += vec3(0.75, 0.9, 1.0) * star * 0.85;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    this.sky = new THREE.Mesh(geo, mat);
    this.sky.frustumCulled = false;
    this.group.add(this.sky);

    // star points add depth
    const n = 700;
    const positions = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      const phi = Math.random() * Math.PI * 2;
      const cost = 0.18 + Math.random() * 0.8;
      const sint = Math.sqrt(1 - cost * cost);
      const r = 210 + Math.random() * 18;
      positions[i * 3] = Math.cos(phi) * sint * r;
      positions[i * 3 + 1] = cost * r;
      positions[i * 3 + 2] = Math.sin(phi) * sint * r;
    }
    const sg = new THREE.BufferGeometry();
    sg.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const sm = new THREE.PointsMaterial({ color: 0x9fd8ff, size: 1.5, sizeAttenuation: true, transparent: true, opacity: 0.8, toneMapped: false });
    this.stars = new THREE.Points(sg, sm);
    this.group.add(this.stars);
  }

  _buildLights() {
    const hemi = new THREE.HemisphereLight(0x78b8ff, 0x09131c, 1.45);
    this.scene.add(hemi);
    this.scene.add(new THREE.AmbientLight(0x29425e, 0.6));

    const key = new THREE.DirectionalLight(0xeaf7ff, 2.5);
    key.position.set(34, 55, 26);
    key.castShadow = true;
    key.shadow.mapSize.set(2048, 2048);
    key.shadow.camera.left = -76;
    key.shadow.camera.right = 76;
    key.shadow.camera.top = 54;
    key.shadow.camera.bottom = -54;
    key.shadow.camera.near = 5;
    key.shadow.camera.far = 140;
    key.shadow.bias = -0.0008;
    key.shadow.normalBias = 0.04;
    this.scene.add(key);
    this.keyLight = key;

    const fill = new THREE.DirectionalLight(0x2d7dff, 0.85);
    fill.position.set(-45, 32, -38);
    this.scene.add(fill);

    this.goalLights = {};
    for (const side of [-1, 1]) {
      const color = side < 0 ? C.blue : C.orange;
      const light = new THREE.PointLight(color, 220, 42, 2);
      light.position.set(side * 64, 8, 0);
      this.scene.add(light);
      this.goalLights[side] = light;
      const l2 = new THREE.PointLight(color, 70, 26, 2);
      l2.position.set(side * 46, 14, 0);
      this.scene.add(l2);
    }

    // overhead rim lights
    for (let i = -2; i <= 2; i++) {
      const l = new THREE.PointLight(0x86dcff, 50, 60, 2);
      l.position.set(i * 22, 27, 0);
      this.scene.add(l);
    }
  }

  _fieldTexture() {
    const W = 2048, H = 1365;
    return canvasTexture(W, H, (ctx) => {
      const px = (x) => ((x + 60) / 120) * W;
      const pz = (z) => ((z + 40) / 80) * H;
      // base
      ctx.fillStyle = '#123c35';
      ctx.fillRect(0, 0, W, H);
      // mowing stripes along the length
      for (let i = 0; i < 12; i++) {
        ctx.fillStyle = i % 2 ? '#0d2e2b' : '#123d36';
        ctx.fillRect((i / 12) * W, 0, W / 12 + 1, H);
      }
      // subtle diagonal sheen
      const sheen = ctx.createLinearGradient(0, 0, W, H);
      sheen.addColorStop(0, 'rgba(70,200,220,0.10)');
      sheen.addColorStop(0.45, 'rgba(30,120,140,0.02)');
      sheen.addColorStop(1, 'rgba(255,130,40,0.07)');
      ctx.fillStyle = sheen;
      ctx.fillRect(0, 0, W, H);

      // hex mesh
      ctx.strokeStyle = 'rgba(100,220,210,0.045)';
      ctx.lineWidth = 1.5;
      const r = 34;
      for (let yy = 0; yy < H + r; yy += r * 1.5) {
        for (let xx = 0; xx < W + r; xx += r * Math.sqrt(3)) {
          const ox = (Math.round(yy / (r * 1.5)) % 2) * r * Math.sqrt(3) / 2;
          ctx.beginPath();
          for (let k = 0; k < 6; k++) {
            const a = Math.PI / 3 * k + Math.PI / 6;
            const x = xx + ox + Math.cos(a) * r;
            const y = yy + Math.sin(a) * r;
            if (k === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
          }
          ctx.closePath();
          ctx.stroke();
        }
      }

      // wear / speckle
      for (let i = 0; i < 5200; i++) {
        const a = Math.random() * 0.09;
        ctx.fillStyle = Math.random() > 0.5 ? `rgba(200,255,240,${a})` : `rgba(0,10,8,${a})`;
        const s = Math.random() * 3;
        ctx.fillRect(Math.random() * W, Math.random() * H, s, s);
      }

      // field lines
      const line = (a = 0.85, width = 5) => { ctx.strokeStyle = `rgba(220,248,255,${a})`; ctx.lineWidth = width; };
      const marginX = px(-54), marginZ = pz(-35);
      line(0.9, 6);
      ctx.strokeRect(marginX, marginZ, px(54) - marginX, pz(35) - marginZ);
      line(0.78, 4);
      ctx.beginPath(); ctx.moveTo(px(0), marginZ); ctx.lineTo(px(0), pz(35)); ctx.stroke();
      ctx.beginPath(); ctx.arc(px(0), pz(0), (pz(10) - pz(0)), 0, Math.PI * 2); ctx.stroke();
      ctx.beginPath(); ctx.arc(px(0), pz(0), 9, 0, Math.PI * 2); ctx.fillStyle = 'rgba(220,248,255,0.9)'; ctx.fill();

      // goal boxes
      for (const side of [-1, 1]) {
        const gx = px(side * 54);
        const dir = -side;
        line(0.8, 4);
        ctx.strokeRect(
          Math.min(gx, gx + dir * (px(18) - px(0))),
          pz(-22),
          Math.abs(px(18) - px(0)),
          pz(22) - pz(-22)
        );
        ctx.strokeRect(
          Math.min(gx, gx + dir * (px(8) - px(0))),
          pz(-13),
          Math.abs(px(8) - px(0)),
          pz(13) - pz(-13)
        );
        // penalty arc
        ctx.beginPath();
        ctx.arc(gx + dir * (px(10) - px(0)), pz(0), pz(11) - pz(0), side < 0 ? -Math.PI / 2 : Math.PI / 2, side < 0 ? Math.PI / 2 : Math.PI * 1.5);
        ctx.stroke();
      }

      // team crests
      for (const side of [-1, 1]) {
        const cx = px(side * 39), cy = pz(0);
        const col = side < 0 ? '#3fdcff' : '#ff9a3c';
        ctx.save();
        ctx.translate(cx, cy);
        ctx.globalAlpha = 0.24;
        ctx.strokeStyle = col; ctx.lineWidth = 5;
        for (let ring = 0; ring < 3; ring++) {
          ctx.beginPath();
          for (let k = 0; k < 6; k++) {
            const a = Math.PI / 3 * k + Math.PI / 6 + ring * 0.09;
            const rr = 66 + ring * 24;
            const x = Math.cos(a) * rr, y = Math.sin(a) * rr;
            if (k === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
          }
          ctx.closePath(); ctx.stroke();
        }
        ctx.globalAlpha = 0.32;
        ctx.fillStyle = col;
        ctx.font = '700 20px "Rajdhani", sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(side < 0 ? 'BLUE' : 'ORANGE', 0, 6);
        ctx.restore();
      }

      // center mark
      ctx.save();
      ctx.translate(px(0), pz(0));
      ctx.globalAlpha = 0.38;
      ctx.strokeStyle = '#dbffff'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(0, 0, 46, 0, Math.PI * 2); ctx.stroke();
      ctx.fillStyle = '#d8ffff';
      ctx.font = '700 22px "Russo One", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('RL · 3D', 0, 8);
      ctx.restore();
    });
  }

  _buildField() {
    // large surrounding slab
    const slab = new THREE.Mesh(
      new THREE.BoxGeometry(166, 2.4, 126),
      new THREE.MeshStandardMaterial({ color: 0x070d15, metalness: 0.6, roughness: 0.45 })
    );
    slab.position.y = -1.22;
    slab.receiveShadow = true;
    this.group.add(slab);

    const tex = this._fieldTexture();
    tex.anisotropy = Math.min(16, this.renderer.capabilities.getMaxAnisotropy());
    const floorMat = new THREE.MeshStandardMaterial({
      map: tex,
      roughness: 0.52,
      metalness: 0.18,
      envMapIntensity: 0.55,
    });
    const floor = new THREE.Mesh(new THREE.PlaneGeometry(120, 80), floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    floor.position.y = 0;
    this.group.add(floor);
    this.floor = floor;

    // subtle glowing boundary rails
    const railMat = neonMaterial(0x6ff2ff, 1.15);
    const railGeoX = new THREE.BoxGeometry(120, 0.09, 0.22);
    const railGeoZ = new THREE.BoxGeometry(0.22, 0.09, 80);
    for (const z of [-39.2, 39.2]) {
      const m = new THREE.Mesh(railGeoX, railMat);
      m.position.set(0, 0.05, z);
      this.group.add(m);
    }
    for (const x of [-59.2, 59.2]) {
      const m = new THREE.Mesh(railGeoZ, railMat);
      m.position.set(x, 0.05, 0);
      this.group.add(m);
    }
  }

  _buildWalls() {
    const glassMat = new THREE.MeshPhysicalMaterial({
      color: 0x6fb8d8,
      metalness: 0.1,
      roughness: 0.12,
      transparent: true,
      opacity: 0.085,
      side: THREE.DoubleSide,
      depthWrite: false,
      envMapIntensity: 0.8,
    });
    const lowerMat = new THREE.MeshStandardMaterial({ color: 0x0d1824, metalness: 0.72, roughness: 0.34 });
    const frameMat = new THREE.MeshStandardMaterial({ color: 0x2c3e50, metalness: 0.9, roughness: 0.28 });
    const trimBlue = neonMaterial(C.blue, 1.15);
    const trimOrange = neonMaterial(C.orange, 1.15);
    const trimIce = neonMaterial(0xa9efff, 0.5, 0.55);

    const addBox = (w, h, d, x, y, z, mat, shadow = false) => {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
      mesh.position.set(x, y, z);
      mesh.castShadow = shadow;
      mesh.receiveShadow = shadow;
      this.group.add(mesh);
      return mesh;
    };

    // side walls
    for (const side of [-1, 1]) {
      const z = side * 40.5;
      addBox(122, 5, 1.2, 0, 2.5, z, lowerMat);
      const glass = addBox(122, 23, 0.3, 0, 17.5, z, glassMat);
      glass.renderOrder = 2;
      // top rail
      addBox(122, 0.5, 1.4, 0, 29.2, z, frameMat);
      // vertical mullions
      for (let x = -60; x <= 60; x += 10) {
        addBox(0.36, 24, 1.45, x, 16.5, z, frameMat);
      }
      // neon strips
      const strip = new THREE.Mesh(new THREE.BoxGeometry(120, 0.12, 0.4), side < 0 ? trimBlue : trimOrange);
      strip.position.set(0, 9.8, z - side * 0.75);
      this.group.add(strip);
      const strip2 = new THREE.Mesh(new THREE.BoxGeometry(120, 0.08, 0.35), trimIce);
      strip2.position.set(0, 20.5, z - side * 0.7);
      this.group.add(strip2);

      // angled support braces
      for (let x = -50; x <= 50; x += 20) {
        const brace = new THREE.Mesh(new THREE.BoxGeometry(0.35, 8, 3.2), frameMat);
        brace.position.set(x, 7.7, z + side * 1.8);
        brace.rotation.x = side * 0.48;
        this.group.add(brace);
      }

      // sponsor boards
      for (let i = 0; i < 4; i++) {
        const board = this._sponsorBoard(i, side);
        board.position.set(-37 + i * 25, 5.1, z - side * 0.72);
        if (side > 0) board.rotation.y = Math.PI;
        this.group.add(board);
      }
    }

    // end walls, split around goal opening
    for (const side of [-1, 1]) {
      const x = side * 60.5;
      const teamTrim = side < 0 ? trimBlue : trimOrange;
      // side segments
      for (const zs of [-1, 1]) {
        addBox(1.2, 5, 27, x, 2.5, zs * 26.5, lowerMat);
        const glass = addBox(0.3, 23, 27, x, 17.5, zs * 26.5, glassMat);
        glass.renderOrder = 2;
        addBox(1.4, 0.5, 27, x, 29.2, zs * 26.5, frameMat);
      }
      // above goal
      addBox(1.2, 5, 26, x, 2.5, 0, lowerMat);
      addBox(1.3, 17, 26, x, 17.5, 0, glassMat);
      addBox(1.5, 0.5, 26, x, 29.2, 0, frameMat);

      const strip = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.14, 80), teamTrim);
      strip.position.set(x - side * 0.7, 9.6, 0);
      this.group.add(strip);
      const strip2 = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.08, 80), trimIce);
      strip2.position.set(x - side * 0.7, 22.5, 0);
      this.group.add(strip2);

      // vertical mullions
      for (const z of [-37, -28, -20, 20, 28, 37]) {
        addBox(1.45, 24, 0.36, x, 16.5, z, frameMat);
      }
    }

    // ceiling truss grid (mostly atmosphere, bolted to walls)
    const trussMat = new THREE.MeshStandardMaterial({ color: 0x192633, metalness: 0.85, roughness: 0.35 });
    for (let x = -50; x <= 50; x += 20) {
      const beam = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.7, 80), trussMat);
      beam.position.set(x, 30.6, 0);
      this.group.add(beam);
    }
    for (let z = -30; z <= 30; z += 20) {
      const beam = new THREE.Mesh(new THREE.BoxGeometry(120, 0.7, 0.7), trussMat);
      beam.position.set(0, 30.6, z);
      this.group.add(beam);
    }

    // rim light ring
    const ring = new THREE.Mesh(new THREE.TorusGeometry(48, 0.28, 8, 96), neonMaterial(0xc9f7ff, 1.25));
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 30.2;
    this.group.add(ring);
  }

  _sponsorBoard(index, side) {
    const words = ['TURBO', 'NEON', 'BOOST', 'AERIAL'];
    const cols = ['#1fc8ff', '#ff7a18', '#9aeaff', '#ffc03f'];
    const cv = document.createElement('canvas');
    cv.width = 512; cv.height = 128;
    const ctx = cv.getContext('2d');
    ctx.fillStyle = '#08131f';
    ctx.fillRect(0, 0, 512, 128);
    ctx.strokeStyle = 'rgba(100,190,230,.35)';
    ctx.lineWidth = 4;
    ctx.strokeRect(3, 3, 506, 122);
    ctx.strokeStyle = cols[index % cols.length];
    ctx.lineWidth = 7;
    ctx.beginPath(); ctx.moveTo(26, 95); ctx.lineTo(84, 30); ctx.stroke();
    ctx.fillStyle = cols[index % cols.length];
    ctx.font = '700 54px "Russo One", sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText(words[index % words.length], 108, 83);
    ctx.fillStyle = 'rgba(170,225,250,.55)';
    ctx.font = '600 17px "Rajdhani", sans-serif';
    ctx.fillText('OMG ARENA SERIES', 110, 108);
    const tex = new THREE.CanvasTexture(cv);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.anisotropy = 8;
    const mat = new THREE.MeshBasicMaterial({ map: tex, toneMapped: false });
    return new THREE.Mesh(new THREE.PlaneGeometry(20, 5), mat);
  }

  _netMaterial(color) {
    const cv = document.createElement('canvas');
    cv.width = 256; cv.height = 256;
    const ctx = cv.getContext('2d');
    ctx.clearRect(0, 0, 256, 256);
    ctx.strokeStyle = color;
    ctx.lineWidth = 2.2;
    ctx.globalAlpha = 0.9;
    for (let i = 0; i <= 16; i++) {
      const p = i * 16;
      ctx.beginPath(); ctx.moveTo(p, 0); ctx.lineTo(p, 256); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, p); ctx.lineTo(256, p); ctx.stroke();
    }
    const tex = new THREE.CanvasTexture(cv);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(4, 2);
    const mat = new THREE.MeshBasicMaterial({
      map: tex,
      color: new THREE.Color(color).multiplyScalar(1.35),
      transparent: true,
      opacity: 0.62,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    return mat;
  }

  _buildGoals() {
    const { goalWidth, goalHeight, goalDepth } = ARENA;
    this.goalFrames = [];
    for (const side of [-1, 1]) {
      const color = side < 0 ? C.blue : C.orange;
      const x = side * 60;
      const g = new THREE.Group();
      g.position.set(x, 0, 0);
      this.group.add(g);

      const frameMat = new THREE.MeshStandardMaterial({
        color,
        emissive: color,
        emissiveIntensity: 2.2,
        metalness: 0.7,
        roughness: 0.2,
        toneMapped: true,
      });
      const postW = 0.7;
      // posts
      for (const z of [-goalWidth / 2, goalWidth / 2]) {
        const post = new THREE.Mesh(new THREE.BoxGeometry(postW, goalHeight, postW), frameMat);
        post.position.set(0, goalHeight / 2, z);
        g.add(post);
      }
      // crossbar
      const bar = new THREE.Mesh(new THREE.BoxGeometry(postW, postW, goalWidth + postW), frameMat);
      bar.position.set(0, goalHeight, 0);
      g.add(bar);
      // inner goal frame trim
      const trimMat = neonMaterial(color, 2.4);
      const glowBar = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.18, goalWidth - 1), trimMat);
      glowBar.position.set(-side * 0.6, goalHeight - 0.45, 0);
      g.add(glowBar);

      // net planes
      const netMat = this._netMaterial(side < 0 ? '#55ddff' : '#ffac55');
      const back = new THREE.Mesh(new THREE.PlaneGeometry(goalWidth, goalHeight), netMat);
      back.rotation.y = -side * Math.PI / 2;
      back.position.set(side * goalDepth, goalHeight / 2, 0);
      g.add(back);
      for (const z of [-goalWidth / 2, goalWidth / 2]) {
        const sideNet = new THREE.Mesh(new THREE.PlaneGeometry(goalDepth, goalHeight), netMat);
        sideNet.rotation.y = 0;
        sideNet.position.set(side * goalDepth / 2, goalHeight / 2, z);
        g.add(sideNet);
      }
      const top = new THREE.Mesh(new THREE.PlaneGeometry(goalDepth, goalWidth), netMat);
      top.rotation.x = Math.PI / 2;
      top.position.set(side * goalDepth / 2, goalHeight, 0);
      g.add(top);

      // goal floor glow
      const glow = new THREE.Mesh(
        new THREE.PlaneGeometry(goalDepth, goalWidth),
        new THREE.MeshBasicMaterial({ color: new THREE.Color(color).multiplyScalar(0.6), transparent: true, opacity: 0.35, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
      );
      glow.rotation.x = -Math.PI / 2;
      glow.position.set(side * goalDepth / 2, 0.05, 0);
      g.add(glow);

      // goal mouth light strip on floor
      const mouth = new THREE.Mesh(
        new THREE.PlaneGeometry(1.1, goalWidth),
        new THREE.MeshBasicMaterial({ color: new THREE.Color(color).multiplyScalar(1.6), transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
      );
      mouth.rotation.x = -Math.PI / 2;
      mouth.position.set(-side * 0.4, 0.07, 0);
      g.add(mouth);

      this.goalFrames.push({ side, group: g, color, frameMat, light: this.goalLights[side] });
    }
  }

  _buildStands() {
    const standMat = new THREE.MeshStandardMaterial({ color: 0x0a1420, metalness: 0.52, roughness: 0.55 });
    const stepMat = new THREE.MeshStandardMaterial({ color: 0x101c2a, metalness: 0.35, roughness: 0.72 });
    const accentBlue = neonMaterial(C.blue, 1.25);
    const accentOrange = neonMaterial(C.orange, 1.25);

    // side stands
    for (const side of [-1, 1]) {
      for (let row = 0; row < 8; row++) {
        const z = side * (47 + row * 3.5);
        const y = 1.1 + row * 1.35;
        const step = new THREE.Mesh(new THREE.BoxGeometry(114, 1.35, 3.55), row % 2 ? standMat : stepMat);
        step.position.set(0, y, z);
        step.receiveShadow = true;
        this.group.add(step);
      }
      const wall = new THREE.Mesh(new THREE.BoxGeometry(118, 18, 1.5), standMat);
      wall.position.set(0, 10, side * 74);
      this.group.add(wall);
      const trim = new THREE.Mesh(new THREE.BoxGeometry(116, 0.22, 0.5), side < 0 ? accentBlue : accentOrange);
      trim.position.set(0, 17.5, side * 73.2);
      this.group.add(trim);
    }

    // end stands behind goals
    for (const side of [-1, 1]) {
      for (let row = 0; row < 6; row++) {
        const x = side * (70 + row * 3.2);
        const y = 1.1 + row * 1.35;
        const step = new THREE.Mesh(new THREE.BoxGeometry(3.25, 1.35, 68), row % 2 ? stepMat : standMat);
        step.position.set(x, y, 0);
        this.group.add(step);
      }
      const wall = new THREE.Mesh(new THREE.BoxGeometry(1.5, 16, 74), standMat);
      wall.position.set(side * 90, 9, 0);
      this.group.add(wall);
      const trim = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.22, 72), side < 0 ? accentBlue : accentOrange);
      trim.position.set(side * 89.2, 15.5, 0);
      this.group.add(trim);
    }
  }

  _buildCrowd() {
    const count = 3600;
    const geo = new THREE.BoxGeometry(0.52, 1.02, 0.46);
    const mat = new THREE.MeshStandardMaterial({ roughness: 0.88, metalness: 0.05 });
    const mesh = new THREE.InstancedMesh(geo, mat, count);
    mesh.frustumCulled = false;
    const dummy = new THREE.Object3D();
    const color = new THREE.Color();
    const palette = [
      0x1b4a66, 0x173b52, 0x255d7a, 0x404852, 0x2b3340,
      0x1ac8ff, 0x1889cc, 0xff7a18, 0xffb34f, 0xd8ecff,
      0x8c1f27, 0x3e2a5e, 0x145c4c,
    ];
    let idx = 0;
    const place = (x, y, z) => {
      if (idx >= count) return;
      dummy.position.set(x, y, z);
      dummy.rotation.set(0, Math.random() * Math.PI * 2, 0);
      dummy.scale.set(0.8 + Math.random() * 0.45, 0.8 + Math.random() * 0.42, 0.8 + Math.random() * 0.35);
      dummy.updateMatrix();
      mesh.setMatrixAt(idx, dummy.matrix);
      const c = palette[Math.floor(Math.random() * palette.length)];
      color.setHex(c).multiplyScalar(0.42 + Math.random() * 0.55);
      mesh.setColorAt(idx, color);
      idx++;
    };

    // side crowd
    for (let row = 0; row < 8; row++) {
      const y = 2.25 + row * 1.35;
      const z = 47 + row * 3.5;
      for (let i = 0; i < 190; i++) {
        const x = -57 + (i / 189) * 114 + (Math.random() - 0.5) * 0.55;
        if (Math.random() < 0.12) continue;
        place(x, y, z + (Math.random() - 0.5) * 1.8);
        if (Math.random() < 0.78) place(x + (Math.random() - 0.5) * 0.65, y, -z + (Math.random() - 0.5) * 1.8);
      }
    }
    // end crowd
    for (let row = 0; row < 6; row++) {
      const y = 2.25 + row * 1.35;
      const x = 70 + row * 3.2;
      for (let i = 0; i < 120; i++) {
        const z = -33 + (i / 119) * 66 + (Math.random() - 0.5) * 0.55;
        if (Math.random() < 0.14) continue;
        place(x + (Math.random() - 0.5) * 1.4, y, z);
        if (Math.random() < 0.76) place(-x + (Math.random() - 0.5) * 1.4, y, z);
      }
    }
    mesh.count = idx;
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    this.group.add(mesh);

    // camera flashes
    const n = 110;
    const pos = new Float32Array(n * 3);
    const colors = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      const side = i % 4;
      let x, y, z;
      if (side < 2) {
        x = -56 + Math.random() * 112;
        z = (side === 0 ? 1 : -1) * (48 + Math.random() * 24);
        y = 2.6 + Math.random() * 11.5;
      } else {
        x = (side === 2 ? 1 : -1) * (71 + Math.random() * 18);
        z = -33 + Math.random() * 66;
        y = 2.6 + Math.random() * 10;
      }
      pos[i * 3] = x; pos[i * 3 + 1] = y; pos[i * 3 + 2] = z;
      colors[i * 3] = 0; colors[i * 3 + 1] = 0; colors[i * 3 + 2] = 0;
      this.flashes.push({ next: Math.random() * 5, life: 0 });
    }
    const fg = new THREE.BufferGeometry();
    fg.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    fg.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    const fm = new THREE.PointsMaterial({
      size: 1.7, map: this._glowTexture(), vertexColors: true, transparent: true,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false, opacity: 0.9,
    });
    this.flashPoints = new THREE.Points(fg, fm);
    this.flashPoints.frustumCulled = false;
    this.group.add(this.flashPoints);
  }

  _glowTexture() {
    if (this._glowTex) return this._glowTex;
    const cv = document.createElement('canvas');
    cv.width = cv.height = 128;
    const ctx = cv.getContext('2d');
    const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
    g.addColorStop(0, 'rgba(255,255,255,1)');
    g.addColorStop(0.22, 'rgba(255,255,255,.9)');
    g.addColorStop(0.55, 'rgba(255,255,255,.25)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 128, 128);
    this._glowTex = new THREE.CanvasTexture(cv);
    return this._glowTex;
  }

  _screenTexture() {
    const cv = document.createElement('canvas');
    cv.width = 768; cv.height = 384;
    const tex = new THREE.CanvasTexture(cv);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.anisotropy = 8;
    return { cv, ctx: cv.getContext('2d'), tex };
  }

  _drawScreen(screen) {
    const { ctx, cv } = screen;
    const s = this.screenState;
    ctx.fillStyle = '#050d18';
    ctx.fillRect(0, 0, cv.width, cv.height);
    // grid
    ctx.strokeStyle = 'rgba(40,170,220,.12)';
    ctx.lineWidth = 1;
    for (let x = 0; x < cv.width; x += 32) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, cv.height); ctx.stroke();
    }
    for (let y = 0; y < cv.height; y += 32) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(cv.width, y); ctx.stroke();
    }
    // header
    ctx.fillStyle = 'rgba(16, 50, 78, .9)';
    ctx.fillRect(0, 0, cv.width, 58);
    ctx.fillStyle = '#86e6ff';
    ctx.font = '700 24px "Russo One", sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('OMG ARENA', 24, 39);
    ctx.textAlign = 'right';
    ctx.fillStyle = '#577e95';
    ctx.font = '600 19px "Rajdhani", sans-serif';
    ctx.fillText('LIVE · NEON DOME', cv.width - 24, 37);

    // score blocks
    const bx = 52, bw = 270, by = 86, bh = 172;
    ctx.fillStyle = 'rgba(14, 70, 105, .55)';
    ctx.fillRect(bx, by, bw, bh);
    ctx.fillStyle = 'rgba(105, 42, 10, .55)';
    ctx.fillRect(cv.width - bx - bw, by, bw, bh);
    ctx.strokeStyle = '#2bd5ff'; ctx.lineWidth = 3;
    ctx.strokeRect(bx, by, bw, bh);
    ctx.strokeStyle = '#ff8a2e';
    ctx.strokeRect(cv.width - bx - bw, by, bw, bh);

    ctx.textAlign = 'center';
    ctx.fillStyle = '#45d6ff';
    ctx.font = '700 31px "Russo One", sans-serif';
    ctx.fillText('BLUE', bx + bw / 2, by + 44);
    ctx.fillStyle = '#ff9b48';
    ctx.fillText('ORANGE', cv.width - bx - bw / 2, by + 44);
    ctx.font = '700 84px "Russo One", sans-serif';
    ctx.fillStyle = '#eafcff';
    ctx.fillText(String(s.blue), bx + bw / 2, by + 132);
    ctx.fillStyle = '#fff1e4';
    ctx.fillText(String(s.orange), cv.width - bx - bw / 2, by + 132);

    // center clock
    ctx.fillStyle = '#e9f9ff';
    ctx.font = '700 53px "Russo One", sans-serif';
    ctx.fillText(s.clock, cv.width / 2, 178);
    ctx.fillStyle = '#58839c';
    ctx.font = '700 15px "Rajdhani", sans-serif';
    ctx.fillText(s.label, cv.width / 2, 204);
    ctx.strokeStyle = 'rgba(100,220,255,.3)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(cv.width / 2 - 55, 224); ctx.lineTo(cv.width / 2 + 55, 224); ctx.stroke();

    // bottom ticker
    ctx.fillStyle = 'rgba(14, 42, 64, .85)';
    ctx.fillRect(0, cv.height - 54, cv.width, 54);
    ctx.fillStyle = '#8de9ff';
    ctx.font = '600 18px "Rajdhani", sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('ROCKET LEAGUE 3D  //  CAR SOCCER', 24, cv.height - 21);
    ctx.textAlign = 'right';
    ctx.fillStyle = '#ffab52';
    ctx.fillText('SEASON 01', cv.width - 24, cv.height - 21);

    screen.tex.needsUpdate = true;
  }

  _buildScreens() {
    this.screens = [];
    const mat = () => {
      const s = this._screenTexture();
      this._drawScreen(s);
      this.screens.push(s);
      return new THREE.MeshBasicMaterial({ map: s.tex, toneMapped: false });
    };
    // side broadcast boards
    for (const side of [-1, 1]) {
      for (const x of [-28, 28]) {
        const m = new THREE.Mesh(new THREE.PlaneGeometry(24, 12), mat());
        m.position.set(x, 18.8, side * 39.6);
        m.rotation.y = side < 0 ? 0 : Math.PI;
        this.group.add(m);
        const frame = new THREE.Mesh(
          new THREE.BoxGeometry(25.2, 13.1, 0.4),
          new THREE.MeshStandardMaterial({ color: 0x101c28, metalness: 0.8, roughness: 0.35 })
        );
        frame.position.set(x, 18.8, side * 39.95);
        this.group.add(frame);
      }
    }
    // main hanging jumbotron
    const jm = new THREE.Mesh(new THREE.BoxGeometry(30, 14, 1), new THREE.MeshBasicMaterial({ map: this.screens[0].tex, toneMapped: false }));
    jm.position.set(0, 30.5, 0);
    jm.rotation.x = Math.PI / 2;
    this.group.add(jm);
  }

  setScore(blue, orange, clock, label) {
    if (this.screenState.blue === blue && this.screenState.orange === orange && this.screenState.clock === clock && this.screenState.label === label) return;
    this.screenState = { blue, orange, clock, label };
    for (const s of this.screens) this._drawScreen(s);
  }

  _buildBoostPads() {
    const smallPositions = [
      [0, 0], [0, -17], [0, 17], [-20, -26], [-20, 26], [20, -26], [20, 26],
      [-36, 0], [36, 0], [-12, -34], [-12, 34], [12, -34], [12, 34],
    ];
    const bigPositions = [[-48, -30], [-48, 30], [48, -30], [48, 30]];
    for (const [x, z] of smallPositions) this._addPad(x, z, false);
    for (const [x, z] of bigPositions) this._addPad(x, z, true);
  }

  _addPad(x, z, big) {
    const group = new THREE.Group();
    group.position.set(x, 0.12, z);
    this.group.add(group);
    const color = big ? 0xffb01e : 0xffdf6a;
    const ringMat = new THREE.MeshBasicMaterial({
      color: new THREE.Color(color).multiplyScalar(big ? 1.8 : 1.1),
      transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    });
    const ring = new THREE.Mesh(new THREE.RingGeometry(big ? 1.55 : 0.72, big ? 1.95 : 0.94, 32), ringMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.03;
    group.add(ring);
    const inner = new THREE.Mesh(
      new THREE.CircleGeometry(big ? 1.45 : 0.62, 24),
      new THREE.MeshBasicMaterial({ color: new THREE.Color(color).multiplyScalar(0.35), transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
    );
    inner.rotation.x = -Math.PI / 2;
    inner.position.y = 0.02;
    group.add(inner);
    const orb = new THREE.Mesh(
      new THREE.SphereGeometry(big ? 0.6 : 0.32, 16, 12),
      new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 2.5, metalness: 0.2, roughness: 0.3 })
    );
    orb.position.y = big ? 1.0 : 0.55;
    group.add(orb);
    const halo = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this._glowTexture(), color: new THREE.Color(color).multiplyScalar(1.5), transparent: true,
      blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.8, toneMapped: false,
    }));
    halo.scale.setScalar(big ? 5.5 : 2.6);
    halo.position.y = big ? 1.1 : 0.6;
    group.add(halo);
    const light = new THREE.PointLight(color, big ? 24 : 9, big ? 15 : 8, 2);
    light.position.y = 1.2;
    group.add(light);

    this.pads.push({
      x, z, big, group, orb, halo, ring, light,
      radius: big ? 4 : 2.3,
      active: true,
      timer: 0,
      respawn: big ? 10 : 4,
      phase: Math.random() * Math.PI * 2,
    });
  }

  takePad(pad) {
    pad.active = false;
    pad.timer = pad.respawn;
    pad.group.visible = false;
    return pad.big ? 100 : 12;
  }

  _buildAtmosphere() {
    // volumetric-ish light shafts
    const beamMat = new THREE.MeshBasicMaterial({
      color: new THREE.Color(0x58ccff).multiplyScalar(1.2),
      transparent: true, opacity: 0.055, blending: THREE.AdditiveBlending,
      depthWrite: false, side: THREE.DoubleSide, toneMapped: false,
    });
    for (const [x, z, rot] of [[-42, -28, -0.3], [42, 28, 0.3], [-42, 28, 0.3], [42, -28, -0.3]]) {
      const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 7.5, 40, 12, 1, true), beamMat);
      beam.position.set(x * 0.8, 17, z * 0.8);
      beam.rotation.z = rot;
      this.group.add(beam);
    }

    // floating dust
    const n = 420;
    const pos = new Float32Array(n * 3);
    this.dustSeeds = [];
    for (let i = 0; i < n; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 110;
      pos[i * 3 + 1] = 1 + Math.random() * 24;
      pos[i * 3 + 2] = (Math.random() - 0.5) * 74;
      this.dustSeeds.push({ speed: 0.12 + Math.random() * 0.35, phase: Math.random() * Math.PI * 2 });
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    const m = new THREE.PointsMaterial({
      color: 0x9bdcff, size: 0.16, transparent: true, opacity: 0.36,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    });
    this.dust = new THREE.Points(g, m);
    this.group.add(this.dust);

    // distant arena halo sprites
    for (const side of [-1, 1]) {
      const halo = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this._glowTexture(), color: side < 0 ? C.blue : C.orange,
        transparent: true, opacity: 0.11, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
      }));
      halo.scale.set(40, 26, 1);
      halo.position.set(side * 88, 10, 0);
      this.group.add(halo);
    }
  }

  update(dt, elapsed, ballPos) {
    this.time += dt;
    // pads
    for (const pad of this.pads) {
      if (pad.active) {
        pad.orb.position.y = (pad.big ? 1.0 : 0.55) + Math.sin(elapsed * 2.4 + pad.phase) * 0.16;
        pad.orb.rotation.y += dt * 1.3;
        pad.halo.material.opacity = 0.62 + Math.sin(elapsed * 3 + pad.phase) * 0.18;
        pad.ring.rotation.z += dt * 0.35;
        pad.light.intensity = (pad.big ? 24 : 9) * (0.8 + Math.sin(elapsed * 3.2 + pad.phase) * 0.2);
      } else {
        pad.timer -= dt;
        if (pad.timer <= 0) {
          pad.active = true;
          pad.group.visible = true;
          pad.group.scale.setScalar(0.01);
        }
      }
      if (pad.active && pad.group.scale.x < 1) {
        const s = Math.min(1, pad.group.scale.x + dt * 2.6);
        pad.group.scale.setScalar(s);
        pad.group.rotation.y = (1 - s) * Math.PI * 2;
      }
    }

    // crowd flashes
    const colors = this.flashPoints.geometry.attributes.color;
    for (let i = 0; i < this.flashes.length; i++) {
      const f = this.flashes[i];
      f.next -= dt;
      if (f.next <= 0) {
        f.next = 0.9 + Math.random() * 6.5;
        f.life = 0.1 + Math.random() * 0.16;
      }
      let v = 0;
      if (f.life > 0) {
        f.life -= dt;
        v = Math.random() > 0.24 ? 2.3 : 0.2;
      }
      colors.array[i * 3] = v;
      colors.array[i * 3 + 1] = v;
      colors.array[i * 3 + 2] = v * 1.12;
    }
    colors.needsUpdate = true;

    // dust drift
    const p = this.dust.geometry.attributes.position;
    for (let i = 0; i < this.dustSeeds.length; i++) {
      const seed = this.dustSeeds[i];
      p.array[i * 3 + 1] += dt * seed.speed * 0.5;
      if (p.array[i * 3 + 1] > 25) p.array[i * 3 + 1] = 1.2;
    }
    p.needsUpdate = true;

    // subtle goal light breathing
    if (this.goalLights) {
      const pulse = 0.86 + Math.sin(elapsed * 1.7) * 0.08;
      this.goalLights[-1].intensity = 220 * pulse;
      this.goalLights[1].intensity = 220 * pulse;
    }
  }

  goalFlash(side, intensity = 1) {
    const light = this.goalLights[side];
    if (!light) return;
    light.intensity = 220 + 900 * intensity;
    setTimeout(() => { light.intensity = 220; }, 900);
  }
}

import * as THREE from 'three';

const MAX = 1600;

function glowTexture() {
  const cv = document.createElement('canvas');
  cv.width = cv.height = 64;
  const ctx = cv.getContext('2d');
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.25, 'rgba(255,255,255,.85)');
  g.addColorStop(0.55, 'rgba(255,255,255,.24)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(cv);
}

export class Effects {
  constructor(scene, renderer) {
    this.scene = scene;
    this.renderer = renderer;
    this.map = glowTexture();

    const geo = new THREE.BufferGeometry();
    this.positions = new Float32Array(MAX * 3);
    this.colors = new Float32Array(MAX * 3);
    this.sizes = new Float32Array(MAX);
    this.alphas = new Float32Array(MAX);
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));
    this.geometry = geo;

    const mat = new THREE.ShaderMaterial({
      uniforms: {
        uMap: { value: this.map },
        uPixelRatio: { value: Math.min(2, renderer.getPixelRatio()) },
      },
      vertexShader: `
        attribute vec3 aColor;
        attribute float aSize;
        attribute float aAlpha;
        varying vec3 vColor;
        varying float vAlpha;
        uniform float uPixelRatio;
        void main() {
          vColor = aColor;
          vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * uPixelRatio * (145.0 / max(0.5, -mv.z));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        uniform sampler2D uMap;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec4 tex = texture2D(uMap, gl_PointCoord);
          gl_FragColor = vec4(vColor * tex.rgb, tex.a * vAlpha);
          if (gl_FragColor.a < 0.01) discard;
        }
      `,
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      depthTest: true,
      toneMapped: false,
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 8;
    scene.add(this.points);

    this.pool = [];
    for (let i = 0; i < MAX; i++) {
      this.pool.push({
        active: false, x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0,
        life: 0, maxLife: 1, size: 1, gravity: 0, drag: 0,
        r: 1, g: 1, b: 1, fade: 1, bounce: false,
      });
    }
    this.cursor = 0;
    this.live = 0;

    this.rings = [];
    this.ringPool = [];
    this._ringGeo = new THREE.RingGeometry(0.82, 1, 64);
    this._emitters = new WeakMap();
    this._ballTrailAcc = 0;
  }

  _spawn(x, y, z, vx, vy, vz, color, size, life, opts = {}) {
    let p = null;
    for (let i = 0; i < MAX; i++) {
      const cand = this.pool[(this.cursor + i) % MAX];
      if (!cand.active) { p = cand; this.cursor = (this.cursor + i + 1) % MAX; break; }
    }
    if (!p) return null;
    p.active = true;
    p.x = x; p.y = y; p.z = z;
    p.vx = vx; p.vy = vy; p.vz = vz;
    p.life = p.maxLife = life;
    p.size = size;
    p.gravity = opts.gravity ?? 0;
    p.drag = opts.drag ?? 0.6;
    p.fade = opts.fade ?? 1;
    p.bounce = opts.bounce ?? false;
    p.r = color.r; p.g = color.g; p.b = color.b;
    return p;
  }

  burst(pos, colorHex, count = 24, power = 12, size = 1.2, life = 0.8, gravity = 18) {
    const color = new THREE.Color(colorHex);
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const u = Math.random() * 2 - 1;
      const s = Math.sqrt(1 - u * u);
      const speed = power * (0.25 + Math.random() * 0.9);
      this._spawn(
        pos.x + (Math.random() - 0.5) * 0.6,
        pos.y + (Math.random() - 0.5) * 0.6,
        pos.z + (Math.random() - 0.5) * 0.6,
        Math.cos(a) * s * speed,
        u * speed + power * 0.25,
        Math.sin(a) * s * speed,
        color, size * (0.5 + Math.random() * 0.9), life * (0.5 + Math.random() * 0.8),
        { gravity, drag: 1.1, fade: 1 }
      );
    }
  }

  hit(pos, colorHex, strength = 1) {
    const color = new THREE.Color(colorHex);
    const count = Math.round(6 + Math.min(26, strength * 9));
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const up = Math.random() * 0.8;
      const speed = 4 + Math.random() * 16 * Math.min(2, strength);
      this._spawn(
        pos.x, pos.y, pos.z,
        Math.cos(a) * speed, up * speed * 0.6, Math.sin(a) * speed,
        color, 0.35 + Math.random() * 0.9, 0.3 + Math.random() * 0.55,
        { gravity: 10, drag: 1.8 }
      );
    }
  }

  boostEmitter(car, colorHex, dt) {
    if (!car || car.isMenu) return;
    let acc = this._emitters.get(car) || 0;
    acc += dt * 90;
    const color = new THREE.Color(colorHex);
    const forward = car.forward;
    const base = car.position;
    while (acc >= 1) {
      acc -= 1;
      for (const sz of [-0.52, 0.52]) {
        const off = new THREE.Vector3(-2.02, 0.02, sz).applyQuaternion(car.quaternion);
        const spread = 2.8;
        this._spawn(
          base.x + off.x, base.y + off.y, base.z + off.z,
          -forward.x * (17 + Math.random() * 10) + (Math.random() - 0.5) * spread,
          -forward.y * (17 + Math.random() * 10) + (Math.random() - 0.5) * spread + 1,
          -forward.z * (17 + Math.random() * 10) + (Math.random() - 0.5) * spread,
          Math.random() < 0.35 ? new THREE.Color(0xffffff) : color,
          0.32 + Math.random() * 0.5,
          0.22 + Math.random() * 0.2,
          { gravity: -2, drag: 2.6, fade: 1 }
        );
      }
    }
    this._emitters.set(car, acc);
  }

  ballTrail(ball, dt, colorHex = 0x74e4ff) {
    const speed = Math.hypot(ball.velocity.x, ball.velocity.y, ball.velocity.z);
    if (speed < 16) return;
    this._ballTrailAcc += dt * Math.min(52, speed * 1.2);
    const color = new THREE.Color(colorHex);
    while (this._ballTrailAcc >= 1) {
      this._ballTrailAcc -= 1;
      this._spawn(
        ball.position.x + (Math.random() - 0.5) * 1.6,
        ball.position.y + (Math.random() - 0.5) * 1.6,
        ball.position.z + (Math.random() - 0.5) * 1.6,
        (Math.random() - 0.5) * 2,
        (Math.random() - 0.5) * 2,
        (Math.random() - 0.5) * 2,
        color, 0.6 + Math.random() * 0.75, 0.28 + Math.random() * 0.36,
        { gravity: 0, drag: 1.2, fade: 1 }
      );
    }
  }

  goalExplosion(pos, colorHex) {
    const color = new THREE.Color(colorHex);
    // core flash
    for (let i = 0; i < 170; i++) {
      const a = Math.random() * Math.PI * 2;
      const b = Math.acos(Math.random() * 2 - 1);
      const speed = 10 + Math.random() * 52;
      this._spawn(
        pos.x, pos.y, pos.z,
        Math.cos(a) * Math.sin(b) * speed,
        Math.cos(b) * speed * 0.7 + 6,
        Math.sin(a) * Math.sin(b) * speed,
        Math.random() < 0.22 ? new THREE.Color(0xffffff) : color,
        0.5 + Math.random() * 1.6, 0.7 + Math.random() * 1.3,
        { gravity: 12, drag: 1.15, fade: 1, bounce: true }
      );
    }
    // confetti from the ceiling
    for (let i = 0; i < 160; i++) {
      const c = Math.random() < 0.5 ? color : new THREE.Color(Math.random() < 0.5 ? 0x22c8ff : 0xff7a18);
      const x = (Math.random() - 0.5) * 92;
      const z = (Math.random() - 0.5) * 64;
      this._spawn(
        x, 24 + Math.random() * 5, z,
        (Math.random() - 0.5) * 6,
        -2 - Math.random() * 5,
        (Math.random() - 0.5) * 6,
        c, 0.45 + Math.random() * 0.5, 2.4 + Math.random() * 2.2,
        { gravity: 8, drag: 0.4, fade: 0.8 }
      );
    }
    this.ring(pos, colorHex, 1.2, 40, 0.9);
    this.ring(pos, 0xffffff, 0.6, 56, 0.7);
  }

  ring(pos, colorHex, start = 1, max = 30, life = 1) {
    const color = new THREE.Color(colorHex);
    let obj = this.ringPool.find(r => !r.active);
    if (!obj) {
      const mat = new THREE.MeshBasicMaterial({
        color, transparent: true, opacity: 0.8, side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
      });
      const mesh = new THREE.Mesh(this._ringGeo, mat);
      mesh.renderOrder = 7;
      this.scene.add(mesh);
      obj = { mesh, active: false };
      this.ringPool.push(obj);
    }
    obj.active = true;
    obj.life = obj.maxLife = life;
    obj.start = start; obj.max = max;
    obj.mesh.position.copy(pos);
    obj.mesh.quaternion.copy(new THREE.Quaternion());
    obj.mesh.scale.setScalar(start);
    obj.mesh.material.color.copy(color).multiplyScalar(1.7);
    obj.mesh.material.opacity = 0.85;
    obj.mesh.visible = true;
    return obj;
  }

  update(dt) {
    const pos = this.positions, col = this.colors, siz = this.sizes, alp = this.alphas;
    let live = 0;
    for (let i = 0; i < MAX; i++) {
      const p = this.pool[i];
      if (!p.active) { alp[i] = 0; continue; }
      p.life -= dt;
      if (p.life <= 0) { p.active = false; alp[i] = 0; continue; }
      live++;
      p.vy += p.gravity * dt;
      const drag = Math.max(0, 1 - p.drag * dt);
      p.vx *= drag; p.vy *= drag; p.vz *= drag;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.z += p.vz * dt;
      if (p.bounce && p.y < 0.18) {
        p.y = 0.18;
        p.vy = Math.abs(p.vy) * 0.35;
        p.vx *= 0.8; p.vz *= 0.8;
      }
      const t = p.life / p.maxLife;
      alp[i] = Math.min(1, t * 2.2) * p.fade;
      pos[i * 3] = p.x; pos[i * 3 + 1] = p.y; pos[i * 3 + 2] = p.z;
      col[i * 3] = p.r; col[i * 3 + 1] = p.g; col[i * 3 + 2] = p.b;
      siz[i] = p.size * (0.65 + t * 0.55);
    }
    this.live = live;
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.aColor.needsUpdate = true;
    this.geometry.attributes.aSize.needsUpdate = true;
    this.geometry.attributes.aAlpha.needsUpdate = true;

    for (const r of this.ringPool) {
      if (!r.active) continue;
      r.life -= dt;
      if (r.life <= 0) { r.active = false; r.mesh.visible = false; continue; }
      const t = 1 - r.life / r.maxLife;
      const s = r.start + (r.max - r.start) * (1 - Math.pow(1 - t, 3));
      r.mesh.scale.setScalar(s);
      r.mesh.material.opacity = (1 - t) * 0.85;
      r.mesh.quaternion.copy(this._ringCameraQuat || new THREE.Quaternion());
    }
  }

  setCameraQuat(q) { this._ringCameraQuat = q; }

  reset() {
    for (const p of this.pool) p.active = false;
    this.alphas.fill(0);
    this.geometry.attributes.aAlpha.needsUpdate = true;
    for (const r of this.ringPool) { r.active = false; r.mesh.visible = false; }
  }
}

import * as THREE from 'three';
import { ARENA } from './arena.js';

function ballTextures() {
  const W = 1024, H = 512;
  const cv = document.createElement('canvas');
  cv.width = W; cv.height = H;
  const ctx = cv.getContext('2d');
  // deep space base
  const grad = ctx.createLinearGradient(0, 0, 0, H);
  grad.addColorStop(0, '#07131f');
  grad.addColorStop(0.5, '#0a1f30');
  grad.addColorStop(1, '#050c15');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // hex panels
  const r = 26;
  for (let row = -1; row < H / (r * 1.5) + 1; row++) {
    for (let col = -1; col < W / (r * Math.sqrt(3)) + 1; col++) {
      const cx = col * r * Math.sqrt(3) + (row % 2 ? r * Math.sqrt(3) / 2 : 0);
      const cy = row * r * 1.5;
      ctx.beginPath();
      for (let k = 0; k < 6; k++) {
        const a = Math.PI / 3 * k + Math.PI / 6;
        const x = cx + Math.cos(a) * (r - 2);
        const y = cy + Math.sin(a) * (r - 2);
        if (k === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.closePath();
      const v = Math.sin(cx * 0.021) * Math.cos(cy * 0.037);
      if (v > 0.38) {
        ctx.fillStyle = 'rgba(120, 210, 240, 0.35)';
        ctx.fill();
      } else if (v < -0.55) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
        ctx.fill();
      }
      ctx.strokeStyle = 'rgba(110, 220, 255, 0.52)';
      ctx.lineWidth = 2.2;
      ctx.stroke();
    }
  }

  // team arcs
  ctx.lineWidth = 13;
  ctx.strokeStyle = 'rgba(32, 200, 255, 0.9)';
  ctx.beginPath(); ctx.ellipse(W * 0.24, H / 2, 42, 105, 0.2, 0, Math.PI * 2); ctx.stroke();
  ctx.strokeStyle = 'rgba(255, 122, 24, 0.9)';
  ctx.beginPath(); ctx.ellipse(W * 0.76, H / 2, 42, 105, -0.2, 0, Math.PI * 2); ctx.stroke();

  // center line / glow
  ctx.strokeStyle = 'rgba(220,250,255,0.75)';
  ctx.lineWidth = 5;
  ctx.beginPath(); ctx.moveTo(W / 2, 0); ctx.lineTo(W / 2, H); ctx.stroke();
  ctx.fillStyle = 'rgba(200,245,255,0.9)';
  ctx.font = '700 46px "Russo One", sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('3D', W / 2, H / 2 + 16);

  // seams dark accents
  for (let i = 0; i < 18; i++) {
    const x = Math.random() * W, y = Math.random() * H;
    ctx.fillStyle = 'rgba(0,0,0,0.26)';
    ctx.beginPath(); ctx.arc(x, y, 8 + Math.random() * 16, 0, Math.PI * 2); ctx.fill();
  }

  const map = new THREE.CanvasTexture(cv);
  map.colorSpace = THREE.SRGBColorSpace;
  map.anisotropy = 8;

  // emissive map
  const ec = document.createElement('canvas');
  ec.width = W; ec.height = H;
  const ex = ec.getContext('2d');
  ex.fillStyle = '#000';
  ex.fillRect(0, 0, W, H);
  ex.lineWidth = 2.2;
  ex.strokeStyle = 'rgba(40, 180, 255, 0.7)';
  for (let row = -1; row < H / (r * 1.5) + 1; row++) {
    for (let col = -1; col < W / (r * Math.sqrt(3)) + 1; col++) {
      const cx = col * r * Math.sqrt(3) + (row % 2 ? r * Math.sqrt(3) / 2 : 0);
      const cy = row * r * 1.5;
      ex.beginPath();
      for (let k = 0; k < 6; k++) {
        const a = Math.PI / 3 * k + Math.PI / 6;
        const x = cx + Math.cos(a) * (r - 2);
        const y = cy + Math.sin(a) * (r - 2);
        if (k === 0) ex.moveTo(x, y); else ex.lineTo(x, y);
      }
      ex.closePath(); ex.stroke();
    }
  }
  ex.lineWidth = 13;
  ex.strokeStyle = 'rgba(0, 180, 255, 0.85)';
  ex.beginPath(); ex.ellipse(W * 0.24, H / 2, 42, 105, 0.2, 0, Math.PI * 2); ex.stroke();
  ex.strokeStyle = 'rgba(255, 100, 0, 0.85)';
  ex.beginPath(); ex.ellipse(W * 0.76, H / 2, 42, 105, -0.2, 0, Math.PI * 2); ex.stroke();
  ex.lineWidth = 4;
  ex.strokeStyle = 'rgba(180, 245, 255, 0.8)';
  ex.beginPath(); ex.moveTo(W / 2, 0); ex.lineTo(W / 2, H); ex.stroke();
  const emissive = new THREE.CanvasTexture(ec);
  emissive.colorSpace = THREE.SRGBColorSpace;

  return { map, emissive };
}

export class Ball {
  constructor(scene) {
    this.scene = scene;
    this.radius = ARENA.ballRadius;
    this.position = new THREE.Vector3(0, this.radius, 0);
    this.velocity = new THREE.Vector3();
    this.angularVelocity = new THREE.Vector3();
    this.scoredAgainst = 0;
    this.onImpact = null;
    this.onGoal = null;
    this.lastTouch = null;
    this.trailAcc = 0;

    const tex = ballTextures();
    const mat = new THREE.MeshPhysicalMaterial({
      map: tex.map,
      emissiveMap: tex.emissive,
      emissive: 0x4fcfff,
      emissiveIntensity: 0.9,
      metalness: 0.32,
      roughness: 0.34,
      clearcoat: 0.9,
      clearcoatRoughness: 0.18,
      envMapIntensity: 1.1,
    });
    this.mesh = new THREE.Mesh(new THREE.SphereGeometry(this.radius, 56, 36), mat);
    this.mesh.castShadow = true;
    this.mesh.receiveShadow = true;
    this.mesh.position.copy(this.position);
    scene.add(this.mesh);

    const glowTex = this._glow();
    this.glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, color: 0x3fd4ff, transparent: true, opacity: 0.34,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    }));
    this.glow.scale.setScalar(this.radius * 4.2);
    scene.add(this.glow);

    this.light = new THREE.PointLight(0x55d6ff, 24, 18, 2);
    scene.add(this.light);
  }

  _glow() {
    const cv = document.createElement('canvas');
    cv.width = cv.height = 128;
    const ctx = cv.getContext('2d');
    const g = ctx.createRadialGradient(64, 64, 7, 64, 64, 64);
    g.addColorStop(0, 'rgba(255,255,255,0.9)');
    g.addColorStop(0.3, 'rgba(255,255,255,0.26)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 128, 128);
    return new THREE.CanvasTexture(cv);
  }

  reset(x = 0, y = this.radius, z = 0, delayDrop = false) {
    this.position.set(x, y, z);
    this.velocity.set(0, 0, 0);
    this.angularVelocity.set(0, 0, 0);
    this.scoredAgainst = 0;
    this.lastTouch = null;
    this.mesh.position.copy(this.position);
    this.mesh.quaternion.identity();
    this.glow.position.copy(this.position);
    this.light.position.copy(this.position);
    this.dropOffset = delayDrop ? 9 : 0;
    if (delayDrop) this.mesh.position.y += this.dropOffset;
  }

  get speed() { return this.velocity.length(); }

  update(dt, effects) {
    if (this.dropOffset > 0) {
      this.dropOffset = Math.max(0, this.dropOffset - dt * 26);
      this.mesh.position.y = this.position.y + this.dropOffset;
      this.glow.position.copy(this.mesh.position);
      this.light.position.copy(this.mesh.position);
      return;
    }

    const r = this.radius;
    const halfL = ARENA.halfLength, halfW = ARENA.halfWidth, ceiling = ARENA.ceiling;
    const goalHalf = ARENA.goalWidth / 2, goalH = ARENA.goalHeight;

    // gravity and drag
    this.velocity.y -= 29 * dt;
    const drag = Math.max(0, 1 - 0.085 * dt);
    this.velocity.multiplyScalar(drag);
    this.position.addScaledVector(this.velocity, dt);

    // --- ground ---
    if (this.position.y < r) {
      this.position.y = r;
      if (this.velocity.y < -3) {
        const s = Math.min(1, Math.abs(this.velocity.y) / 34);
        this.velocity.y = -this.velocity.y * 0.64;
        this.velocity.x *= 0.97;
        this.velocity.z *= 0.97;
        this._impact(s, new THREE.Vector3(this.position.x, 0.08, this.position.z));
      } else {
        this.velocity.y = 0;
        // rolling friction
        const f = Math.max(0, 1 - 0.55 * dt);
        this.velocity.x *= f;
        this.velocity.z *= f;
      }
    }

    // --- ceiling ---
    if (this.position.y > ceiling - r) {
      this.position.y = ceiling - r;
      if (this.velocity.y > 1) {
        this.velocity.y = -this.velocity.y * 0.58;
        this._impact(0.4, this.position.clone());
      }
    }

    // --- side walls ---
    if (this.position.z > halfW - r) {
      this.position.z = halfW - r;
      if (this.velocity.z > 0) {
        this.velocity.z = -this.velocity.z * 0.78;
        this.velocity.x *= 0.985;
        this._impact(Math.min(1, Math.abs(this.velocity.z) / 28), this.position.clone());
      }
    } else if (this.position.z < -halfW + r) {
      this.position.z = -halfW + r;
      if (this.velocity.z < 0) {
        this.velocity.z = -this.velocity.z * 0.78;
        this.velocity.x *= 0.985;
        this._impact(Math.min(1, Math.abs(this.velocity.z) / 28), this.position.clone());
      }
    }

    // --- end walls / goal opening ---
    const inMouth = Math.abs(this.position.z) < goalHalf - r * 0.15 && this.position.y < goalH - r * 0.05;
    if (this.position.x > halfL - r) {
      if (!inMouth) {
        this.position.x = halfL - r;
        if (this.velocity.x > 0) {
          this.velocity.x = -this.velocity.x * 0.76;
          this.velocity.z *= 0.985;
          this._impact(Math.min(1, Math.abs(this.velocity.x) / 30), this.position.clone());
        }
      } else if (this.position.x > halfL + 0.5 && this.scoredAgainst === 0) {
        this.scoredAgainst = 1;
        this.onGoal?.(1, this.position.clone());
      }
    } else if (this.position.x < -halfL + r) {
      if (!inMouth) {
        this.position.x = -halfL + r;
        if (this.velocity.x < 0) {
          this.velocity.x = -this.velocity.x * 0.76;
          this.velocity.z *= 0.985;
          this._impact(Math.min(1, Math.abs(this.velocity.x) / 30), this.position.clone());
        }
      } else if (this.position.x < -halfL - 0.5 && this.scoredAgainst === 0) {
        this.scoredAgainst = -1;
        this.onGoal?.(-1, this.position.clone());
      }
    }

    // inside goal: back net and side nets (unless already scored / frozen)
    if (Math.abs(this.position.x) > halfL) {
      const side = Math.sign(this.position.x);
      const backX = side * (halfL + ARENA.goalDepth - r);
      if (side > 0 ? this.position.x > backX : this.position.x < backX) {
        this.position.x = backX;
        this.velocity.x *= -0.28;
        this.velocity.y *= 0.7;
        this.velocity.z *= 0.7;
      }
      if (Math.abs(this.position.z) > goalHalf - r * 0.1) {
        this.position.z = Math.sign(this.position.z) * (goalHalf - r * 0.1);
        this.velocity.z *= -0.4;
      }
      if (this.position.y > goalH - r * 0.1) {
        this.position.y = goalH - r * 0.1;
        this.velocity.y = -Math.abs(this.velocity.y) * 0.3;
      }
    }

    // visual rotation
    const speed = this.velocity.length();
    const axis = new THREE.Vector3(-this.velocity.z, 0, this.velocity.x);
    if (axis.lengthSq() > 0.0001) {
      axis.normalize();
      this.mesh.rotateOnWorldAxis(axis, (speed / this.radius) * dt);
    }
    this.angularVelocity.multiplyScalar(0.995);

    // sync
    this.mesh.position.copy(this.position);
    this.glow.position.copy(this.position);
    this.glow.material.opacity = 0.22 + Math.min(0.32, speed / 120);
    this.light.position.copy(this.position);
    this.light.intensity = 16 + Math.min(45, speed * 0.8);

    if (effects) effects.ballTrail(this, dt, 0x74e4ff);
  }

  _impact(strength, pos) {
    if (this.onImpact) this.onImpact(strength, pos);
  }

  kick(velocity, spin = 0) {
    this.velocity.copy(velocity);
    this.angularVelocity.set((Math.random() - 0.5) * spin, (Math.random() - 0.5) * spin, (Math.random() - 0.5) * spin);
  }
}

import * as THREE from 'three';
import { ARENA } from './arena.js';

const TEAM_COLORS = {
  blue: {
    paint: 0x0d8fe8, paint2: 0x28cbff, accent: 0x0745c8,
    glow: 0x37d9ff, flame: 0x54e0ff, dark: 0x061521,
  },
  orange: {
    paint: 0xe26211, paint2: 0xffa23f, accent: 0xb62d00,
    glow: 0xff9a42, flame: 0xffb15c, dark: 0x210b03,
  },
};

const wheelGeo = new THREE.CylinderGeometry(0.5, 0.5, 0.44, 22, 1);
wheelGeo.rotateX(Math.PI / 2);
const rimGeo = new THREE.CylinderGeometry(0.27, 0.27, 0.46, 20, 1);
rimGeo.rotateX(Math.PI / 2);

function glowTexture() {
  const cv = document.createElement('canvas');
  cv.width = cv.height = 128;
  const ctx = cv.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.32, 'rgba(255,255,255,.7)');
  g.addColorStop(0.65, 'rgba(255,255,255,.14)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(cv);
}
let sharedGlow = null;
function getGlow() { return sharedGlow || (sharedGlow = glowTexture()); }

function bodyGeometry() {
  const s = new THREE.Shape();
  s.moveTo(-2.14, -0.2);
  s.lineTo(-1.8, -0.3);
  s.lineTo(1.72, -0.3);
  s.lineTo(2.13, -0.12);
  s.lineTo(2.18, 0.08);
  s.lineTo(1.9, 0.21);
  s.lineTo(1.1, 0.3);
  s.lineTo(0.25, 0.35);
  s.lineTo(-1.15, 0.33);
  s.lineTo(-1.9, 0.22);
  s.lineTo(-2.18, 0.03);
  s.closePath();
  const geo = new THREE.ExtrudeGeometry(s, {
    depth: 1.84, bevelEnabled: true, bevelSegments: 4,
    bevelSize: 0.09, bevelThickness: 0.08, curveSegments: 8,
  });
  geo.translate(0, 0, -0.92);
  return geo;
}

function cabinGeometry() {
  const s = new THREE.Shape();
  s.moveTo(-1.05, 0.26);
  s.lineTo(1.02, 0.29);
  s.lineTo(0.66, 0.68);
  s.lineTo(-0.03, 0.79);
  s.lineTo(-0.8, 0.72);
  s.lineTo(-1.08, 0.53);
  s.closePath();
  const geo = new THREE.ExtrudeGeometry(s, {
    depth: 1.34, bevelEnabled: true, bevelSegments: 3,
    bevelSize: 0.055, bevelThickness: 0.05,
  });
  geo.translate(0, 0, -0.67);
  return geo;
}

export class Car {
  constructor(scene, { team = 'blue', isPlayer = false, name = 'CAR', index = 0 } = {}) {
    this.scene = scene;
    this.team = team;
    this.isPlayer = isPlayer;
    this.name = name;
    this.index = index;
    this.colors = TEAM_COLORS[team];

    this.position = new THREE.Vector3();
    this.velocity = new THREE.Vector3();
    this.quaternion = new THREE.Quaternion();
    this.yaw = 0;
    this.grounded = true;
    this.boosting = false;
    this.boost = 33;
    this.jumps = 0;
    this.jumpTimer = 0;
    this.airTime = 0;
    this.hitCooldown = 0;
    this.flipPower = 0;
    this.steerVisual = 0;
    this.wheelSpin = 0;
    this.throttleVisual = 0;
    this.speed = 0;
    this.stun = 0;
    this.angVel = new THREE.Vector3();
    this.landFlash = 0;
    this.boostingVisual = 0;
    this.lastImpact = 0;

    this.hooks = { onBallHit: null, onLand: null, onJump: null, onFlip: null };

    this._buildModel();
    this._tmp = {
      v1: new THREE.Vector3(), v2: new THREE.Vector3(), v3: new THREE.Vector3(),
      q1: new THREE.Quaternion(), q2: new THREE.Quaternion(), q3: new THREE.Quaternion(),
      e1: new THREE.Euler(),
    };
  }

  _buildModel() {
    const c = this.colors;
    const root = this.root = new THREE.Group();
    root.name = `car-${this.name}`;
    this.scene.add(root);
    const body = this.bodyGroup = new THREE.Group();
    root.add(body);
    const wheels = this.wheelGroup = new THREE.Group();
    root.add(wheels);

    const paint = new THREE.MeshPhysicalMaterial({
      color: c.paint, metalness: 0.62, roughness: 0.25,
      clearcoat: 1, clearcoatRoughness: 0.14, envMapIntensity: 1.35,
    });
    const accent = new THREE.MeshStandardMaterial({ color: c.accent, metalness: 0.75, roughness: 0.3, envMapIntensity: 1.1 });
    const trim = new THREE.MeshStandardMaterial({ color: c.paint2, metalness: 0.55, roughness: 0.3, emissive: c.glow, emissiveIntensity: 0.22 });
    const glass = new THREE.MeshPhysicalMaterial({
      color: 0x071522, metalness: 0.75, roughness: 0.1,
      clearcoat: 1, clearcoatRoughness: 0.06, envMapIntensity: 1.6,
    });
    const carbon = new THREE.MeshStandardMaterial({ color: 0x0b1017, metalness: 0.7, roughness: 0.38 });
    const rubber = new THREE.MeshStandardMaterial({ color: 0x090c10, roughness: 0.84, metalness: 0.1 });
    const rimMat = new THREE.MeshStandardMaterial({ color: 0xbdd8e8, metalness: 1, roughness: 0.18, envMapIntensity: 1.5 });
    const rimGlow = new THREE.MeshBasicMaterial({ color: new THREE.Color(c.glow).multiplyScalar(1.8), toneMapped: false });
    const lamp = new THREE.MeshBasicMaterial({ color: new THREE.Color(0xcdf6ff).multiplyScalar(2.4), toneMapped: false });
    const tail = new THREE.MeshBasicMaterial({ color: new THREE.Color(0xff2a12).multiplyScalar(2.2), toneMapped: false });

    const chassis = new THREE.Mesh(bodyGeometry(), paint);
    chassis.castShadow = true;
    chassis.receiveShadow = true;
    body.add(chassis);

    const cabin = new THREE.Mesh(cabinGeometry(), glass);
    cabin.position.y = 0.01;
    cabin.castShadow = true;
    body.add(cabin);

    // roof / center stripe
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.035, 0.24), trim);
    stripe.position.set(-0.05, 0.372, 0);
    body.add(stripe);
    const hoodStripe = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.03, 0.22), trim);
    hoodStripe.position.set(1.55, 0.235, 0);
    body.add(hoodStripe);
    const rearStripe = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.03, 0.2), trim);
    rearStripe.position.set(-1.55, 0.25, 0);
    body.add(rearStripe);

    // side blades
    for (const z of [-0.97, 0.97]) {
      const blade = new THREE.Mesh(new THREE.BoxGeometry(1.9, 0.1, 0.12), accent);
      blade.position.set(-0.05, 0.04, z);
      body.add(blade);
      const skirt = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.13, 0.14), carbon);
      skirt.position.set(-0.05, -0.29, z * 1.04);
      body.add(skirt);
    }

    // splitter + diffuser
    const splitter = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.07, 2.1), carbon);
    splitter.position.set(2.12, -0.28, 0);
    body.add(splitter);
    const diffuser = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.13, 1.8), carbon);
    diffuser.position.set(-2.1, -0.23, 0);
    body.add(diffuser);

    // spoiler
    const wing = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.07, 1.85), trim);
    wing.position.set(-1.9, 0.62, 0);
    wing.rotation.z = -0.06;
    body.add(wing);
    for (const z of [-0.7, 0.7]) {
      const strut = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.35, 0.1), carbon);
      strut.position.set(-1.88, 0.43, z);
      body.add(strut);
    }
    // little canards
    for (const z of [-1.0, 1.0]) {
      const canard = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.04, 0.3), accent);
      canard.position.set(1.72, -0.1, z);
      canard.rotation.z = 0.08;
      body.add(canard);
    }

    // headlights
    for (const z of [-0.63, 0.63]) {
      const lightBox = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.1, 0.42), lamp);
      lightBox.position.set(2.145, 0.04, z);
      body.add(lightBox);
      const glow = new THREE.Sprite(new THREE.SpriteMaterial({
        map: getGlow(), color: 0xa9efff, transparent: true, opacity: 0.6,
        blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
      }));
      glow.scale.setScalar(0.9);
      glow.position.set(2.2, 0.04, z);
      body.add(glow);
    }
    // taillights
    for (const z of [-0.6, 0.6]) {
      const box = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.09, 0.38), tail);
      box.position.set(-2.19, 0.07, z);
      body.add(box);
    }

    // exhausts
    this.exhaustGlows = [];
    for (const z of [-0.52, 0.52]) {
      const pipe = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.13, 0.34, 12), carbon);
      pipe.rotation.z = Math.PI / 2;
      pipe.position.set(-2.17, -0.12, z);
      body.add(pipe);
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.11, 0.02, 6, 16), rimGlow);
      ring.rotation.y = Math.PI / 2;
      ring.position.set(-2.34, -0.12, z);
      body.add(ring);

      const flame = new THREE.Sprite(new THREE.SpriteMaterial({
        map: getGlow(), color: c.flame, transparent: true, opacity: 0,
        blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
      }));
      flame.scale.set(1.4, 1, 1);
      flame.position.set(-2.65, -0.12, z);
      body.add(flame);
      this.exhaustGlows.push(flame);
    }

    // boost point light
    this.boostLight = new THREE.PointLight(c.glow, 0, 9, 2);
    this.boostLight.position.set(-2.5, 0.2, 0);
    root.add(this.boostLight);

    // wheels
    this.wheels = [];
    for (const x of [-1.38, 1.38]) {
      for (const z of [-0.98, 0.98]) {
        const front = x > 0;
        const pivot = new THREE.Group();
        pivot.position.set(x, -0.32, z);
        const wheel = new THREE.Mesh(wheelGeo, rubber);
        wheel.castShadow = true;
        pivot.add(wheel);
        const rim = new THREE.Mesh(rimGeo, rimMat);
        rim.position.z = z > 0 ? 0.01 : -0.01;
        wheel.add(rim);
        // glowing hub ring
        const hub = new THREE.Mesh(new THREE.TorusGeometry(0.2, 0.035, 6, 18), rimGlow);
        hub.position.z = z > 0 ? 0.235 : -0.235;
        hub.rotation.y = 0;
        wheel.add(hub);
        wheels.add(pivot);
        this.wheels.push({ pivot, wheel, front, side: Math.sign(z) });
      }
    }

    // under-glow on the floor (separate so it stays flat)
    const gtex = getGlow();
    this.groundGlow = new THREE.Mesh(
      new THREE.PlaneGeometry(1, 1),
      new THREE.MeshBasicMaterial({
        map: gtex, color: new THREE.Color(c.glow).multiplyScalar(1.1), transparent: true,
        opacity: 0.24, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
      })
    );
    this.groundGlow.rotation.x = -Math.PI / 2;
    this.groundGlow.scale.set(6, 10, 1);
    this.scene.add(this.groundGlow);

    // player marker
    if (this.isPlayer) {
      const marker = this.marker = new THREE.Group();
      const ringMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(0xffd257).multiplyScalar(2.0), toneMapped: false });
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.42, 0.05, 6, 24), ringMat);
      ring.rotation.x = Math.PI / 2;
      marker.add(ring);
      const cone = new THREE.Mesh(new THREE.ConeGeometry(0.22, 0.55, 4), ringMat);
      cone.rotation.x = Math.PI;
      cone.position.y = 0.35;
      marker.add(cone);
      marker.position.y = 2.3;
      this.scene.add(marker);
    }

    this.root.position.copy(this.position);
    this.root.quaternion.copy(this.quaternion);
  }

  reset(x, z, yaw = 0) {
    this.position.set(x, ARENA.carBaseY, z);
    this.velocity.set(0, 0, 0);
    this.yaw = yaw;
    this.quaternion.setFromEuler(new THREE.Euler(0, -yaw, 0));
    this.grounded = true;
    this.boost = 33;
    this.jumps = 0;
    this.jumpTimer = 0;
    this.airTime = 0;
    this.angVel.set(0, 0, 0);
    this.flipPower = 0;
    this.stun = 0;
    this.speed = 0;
    this.steerVisual = 0;
    this.wheelSpin = 0;
    this.bodyGroup.rotation.set(0, 0, 0);
    this.root.position.copy(this.position);
    this.root.quaternion.copy(this.quaternion);
    this.groundGlow.position.set(x, 0.055, z);
    this._syncVisuals(0, 0);
  }

  get forward() {
    return this._tmp.v1.set(1, 0, 0).applyQuaternion(this.quaternion);
  }

  get right() {
    return this._tmp.v2.set(0, 0, 1).applyQuaternion(this.quaternion);
  }

  update(dt, controls, world) {
    const ball = world.ball;
    this.hitCooldown = Math.max(0, this.hitCooldown - dt);
    this.jumpTimer = Math.max(0, this.jumpTimer - dt);
    this.flipPower = Math.max(0, this.flipPower - dt * 2.6);
    this.stun = Math.max(0, this.stun - dt);
    this.landFlash = Math.max(0, this.landFlash - dt * 2);

    const throttle = this.stun > 0 ? 0 : controls.throttle || 0;
    const steer = this.stun > 0 ? 0 : controls.steer || 0;
    const jumpPressed = controls.jumpPressed && this.stun <= 0;
    const wantBoost = controls.boost && this.boost > 0.4 && this.stun <= 0;

    this.boosting = false;
    this.throttleVisual += (throttle - this.throttleVisual) * Math.min(1, dt * 9);

    const forward = this._tmp.v1.set(1, 0, 0).applyQuaternion(this.quaternion);
    const right = this._tmp.v2.set(0, 0, 1).applyQuaternion(this.quaternion);

    if (this.grounded) {
      this.airTime = 0;
      const fwdFlat = new THREE.Vector3(Math.cos(this.yaw), 0, Math.sin(this.yaw));
      const rightFlat = new THREE.Vector3(-Math.sin(this.yaw), 0, Math.cos(this.yaw));
      let fwdSpeed = this.velocity.dot(fwdFlat);
      const latSpeed = this.velocity.dot(rightFlat);

      let accel = 0;
      if (throttle > 0.02) {
        accel = 30 * throttle;
      } else if (throttle < -0.02) {
        if (fwdSpeed > 2) accel = 46 * throttle;
        else accel = 15 * throttle;
      }
      if (wantBoost) {
        accel += 33;
        this.boosting = true;
        this.boost = Math.max(0, this.boost - 33 * dt);
      }
      this.velocity.addScaledVector(fwdFlat, accel * dt);

      // rolling resistance / brake
      const spd = this.velocity.length();
      const resist = (throttle === 0 ? 1.6 : 0.7) + spd * spd * 0.0022;
      this.velocity.multiplyScalar(Math.max(0, 1 - resist * dt));

      // lateral grip (cut sideways speed)
      const lat = this.velocity.dot(rightFlat);
      this.velocity.addScaledVector(rightFlat, -lat * Math.min(1, dt * (controls.drift ? 3.6 : 10.5)));
      // small drift when handbrake is held via S at speed? keep planted.

      // steering
      fwdSpeed = this.velocity.dot(fwdFlat);
      const speedAuthority = Math.min(1, 0.4 + Math.abs(fwdSpeed) / 18);
      const dir = fwdSpeed < -0.5 ? -1 : 1;
      this.yaw += steer * 2.25 * speedAuthority * dir * dt * (1 - Math.min(0.3, spd / 260));
      if (wantBoost && Math.abs(fwdSpeed) > 4) this.yaw += steer * 0.35 * dt;

      // speed caps
      const cap = this.boosting ? 59 : 38;
      const maxV = Math.max(cap, Math.abs(fwdSpeed));
      const vlen = this.velocity.length();
      if (vlen > maxV) this.velocity.multiplyScalar(maxV / vlen);

      // settle on ground
      this.position.y = ARENA.carBaseY;
      this.velocity.y = 0;

      // align car to ground plane and yaw
      const target = this._tmp.q1.setFromEuler(this._tmp.e1.set(0, -this.yaw, 0));
      this.quaternion.slerp(target, Math.min(1, dt * 13));
      this.angVel.multiplyScalar(Math.max(0, 1 - dt * 12));

      // jump
      if (jumpPressed) {
        this.velocity.y = 13.6;
        this.grounded = false;
        this.jumps = 1;
        this.jumpTimer = 0.18;
        this.airTime = 0;
        this.hooks.onJump?.(this);
        // lift with a little nose-up
        this._applyLocalRotation(0, 0, 0.1);
      }
    } else {
      this.airTime += dt;
      this.velocity.y -= 31 * dt;

      if (wantBoost) {
        this.boosting = true;
        this.boost = Math.max(0, this.boost - 33 * dt);
        this.velocity.addScaledVector(forward, 35 * dt);
      }

      // air drag
      this.velocity.multiplyScalar(Math.max(0, 1 - 0.1 * dt));

      // air control: local pitch (W/S), yaw (A/D), roll (Q/E)
      const roll = controls.roll || 0;
      const targetPitch = -throttle * 4.6;
      const targetYaw = -steer * 3.6;
      const targetRoll = roll * 4.8;
      this.angVel.x += (targetRoll - this.angVel.x) * Math.min(1, dt * 7);
      this.angVel.y += (targetYaw - this.angVel.y) * Math.min(1, dt * 7);
      this.angVel.z += (targetPitch - this.angVel.z) * Math.min(1, dt * 7);
      if (Math.abs(roll) < 0.01 && this.angVel.x !== 0) this.angVel.x *= Math.max(0, 1 - dt * 1.2);
      this._applyLocalRotation(this.angVel.x * dt, this.angVel.y * dt, this.angVel.z * dt);

      // double jump / flip
      if (jumpPressed && this.jumps === 1 && this.jumpTimer <= 0) {
        this.jumps = 2;
        this.flipPower = 1;
        const dodge = new THREE.Vector3(forward.x * throttle + right.x * steer, 0, forward.z * throttle + right.z * steer);
        if (dodge.lengthSq() > 0.04) {
          dodge.normalize();
          this.velocity.addScaledVector(dodge, 15);
          this.velocity.y = Math.max(this.velocity.y, 4.2);
          // spin around the axis perpendicular to dodge for a visible flip
          const axis = new THREE.Vector3().crossVectors(new THREE.Vector3(0, 1, 0), dodge).normalize();
          this.angVel.addScaledVector(axis, -14);
          this._applyLocalRotation(0, 0, 0);
        } else {
          this.velocity.y = 10.8;
          this.angVel.multiplyScalar(0.5);
        }
        this.jumpTimer = 0.25;
        this.hooks.onFlip?.(this);
      }

      if (this.velocity.y < -55) this.velocity.y = -55;

      // land
      if (this.position.y <= ARENA.carBaseY && this.velocity.y <= 0) {
        const spd = Math.hypot(this.velocity.x, this.velocity.z);
        this.position.y = ARENA.carBaseY;
        this.velocity.y = 0;
        this.grounded = true;
        this.jumps = 0;
        this.airTime = 0;
        this.landFlash = 1;
        this.angVel.multiplyScalar(0);
        const fwd = forward;
        if (Math.hypot(fwd.x, fwd.z) > 0.1) this.yaw = Math.atan2(fwd.z, fwd.x);
        const target = this._tmp.q1.setFromEuler(this._tmp.e1.set(0, -this.yaw, 0));
        this.quaternion.slerp(target, 0.8);
        this.hooks.onLand?.(this, spd);
      }
    }

    // integrate
    this.position.addScaledVector(this.velocity, dt);

    // arena bounds
    const xLimit = ARENA.halfLength - 2.7;
    const zLimit = ARENA.halfWidth - 1.9;
    if (this.position.x > xLimit) { this.position.x = xLimit; if (this.velocity.x > 0) this.velocity.x *= -0.25; }
    if (this.position.x < -xLimit) { this.position.x = -xLimit; if (this.velocity.x < 0) this.velocity.x *= -0.25; }
    if (this.position.z > zLimit) { this.position.z = zLimit; if (this.velocity.z > 0) this.velocity.z *= -0.25; }
    if (this.position.z < -zLimit) { this.position.z = -zLimit; if (this.velocity.z < 0) this.velocity.z *= -0.25; }
    if (this.position.y < ARENA.carBaseY) {
      this.position.y = ARENA.carBaseY;
      if (!this.grounded && this.velocity.y <= 0) {
        this.grounded = true;
        this.jumps = 0;
        this.velocity.y = 0;
      }
    }

    this.speed = this.velocity.length();
    this.steerVisual += (steer - this.steerVisual) * Math.min(1, dt * 12);
    this.wheelSpin -= this.speed * dt / 0.5;

    // ball collision
    if (ball) this._collideBall(ball);

    this._syncVisuals(dt, steer);
  }

  _applyLocalRotation(x, y, z) {
    const q = this._tmp.q2;
    if (x) { q.setFromAxisAngle(this._tmp.v3.set(1, 0, 0), x); this.quaternion.multiply(q); }
    if (y) { q.setFromAxisAngle(this._tmp.v3.set(0, 1, 0), y); this.quaternion.multiply(q); }
    if (z) { q.setFromAxisAngle(this._tmp.v3.set(0, 0, 1), z); this.quaternion.multiply(q); }
    this.quaternion.normalize();
  }

  _collideBall(ball) {
    const qInv = this._tmp.q1.copy(this.quaternion).invert();
    const local = this._tmp.v1.copy(ball.position).sub(this.position).applyQuaternion(qInv);
    // chassis half-extents (slightly forgiving)
    const hx = 2.22, hy = 0.52, hz = 1.06;
    const cx = Math.max(-hx, Math.min(hx, local.x));
    const cy = Math.max(-hy, Math.min(hy, local.y));
    const cz = Math.max(-hz, Math.min(hz, local.z));
    const dx = local.x - cx, dy = local.y - cy, dz = local.z - cz;
    const distSq = dx * dx + dy * dy + dz * dz;
    const r = ball.radius;
    if (distSq > r * r) return;

    let dist = Math.sqrt(distSq);
    let nx, ny, nz;
    if (dist < 0.0001) {
      // deep overlap: push out through nearest face
      const px = hx - Math.abs(local.x);
      const py = hy - Math.abs(local.y);
      const pz = hz - Math.abs(local.z);
      if (px < py && px < pz) { nx = Math.sign(local.x) || 1; ny = 0; nz = 0; dist = 0; }
      else if (py < pz) { nx = 0; ny = Math.sign(local.y) || 1; nz = 0; dist = 0; }
      else { nx = 0; ny = 0; nz = Math.sign(local.z) || 1; dist = 0; }
    } else {
      nx = dx / dist; ny = dy / dist; nz = dz / dist;
    }

    const normal = this._tmp.v2.set(nx, ny, nz).applyQuaternion(this.quaternion).normalize();
    const pen = r - dist;
    ball.position.addScaledVector(normal, pen + 0.02);

    const rel = this._tmp.v3.copy(ball.velocity).sub(this.velocity);
    const vn = rel.dot(normal);
    const carSpeed = this.velocity.length();

    if (this.hitCooldown <= 0) {
      let strength = 0;
      if (vn < 0) {
        const e = 0.62;
        const impulse = -(1 + e) * vn * 0.96; // ball mass 1, car effectively much heavier
        ball.velocity.addScaledVector(normal, impulse);
        strength = Math.min(2.2, Math.abs(vn) / 18 + carSpeed / 45);
      }
      // transfer momentum from the car's motion into the ball
      const carAlong = Math.max(0, this.velocity.dot(normal));
      if (carAlong > 0.2) {
        ball.velocity.addScaledVector(normal, carAlong * 0.72);
        strength = Math.max(strength, Math.min(2.2, carAlong / 24));
      }
      // nose/flip hits pop the ball
      const upward = Math.min(9.5, Math.abs(vn) * 0.16 + carSpeed * 0.07 + this.flipPower * 3.4);
      ball.velocity.y += upward;
      if (this.flipPower > 0.2) {
        ball.velocity.addScaledVector(this.forward, this.flipPower * 11);
        ball.velocity.y += this.flipPower * 4;
        strength += this.flipPower * 1.2;
      }

      // spin ball with a bit of side english
      ball.angularVelocity.add(new THREE.Vector3(
        (Math.random() - 0.5) * strength * 9,
        (Math.random() - 0.5) * strength * 9,
        (Math.random() - 0.5) * strength * 9
      ));

      // car loses a touch of speed
      this.velocity.multiplyScalar(0.978);
      if (strength > 0.15) {
        this.hitCooldown = 0.09;
        this.hooks.onBallHit?.(this, strength, ball);
      }
      this.lastImpact = strength;
    }
  }

  _syncVisuals(dt, steer) {
    this.root.position.copy(this.position);
    this.root.quaternion.copy(this.quaternion);

    // body lean / pitch
    const spd = Math.min(1, Math.abs(this.velocity.length()) / 45);
    const targetRoll = this.grounded ? -this.steerVisual * 0.075 * spd : 0;
    const targetPitch = this.grounded
      ? Math.max(-0.06, Math.min(0.06, (this.grounded ? -this.throttleVisual : 0) * 0.025 + (this.boosting ? 0.02 : 0)))
      : 0;
    this.bodyGroup.rotation.x += (targetRoll - this.bodyGroup.rotation.x) * Math.min(1, (dt || 0.016) * 10);
    this.bodyGroup.rotation.z += (targetPitch - this.bodyGroup.rotation.z) * Math.min(1, (dt || 0.016) * 10);

    // wheels
    for (const w of this.wheels) {
      w.wheel.rotation.z = this.wheelSpin;
      if (w.front) w.pivot.rotation.y = -this.steerVisual * 0.4;
    }

    // boost flames
    this.boostingVisual += ((this.boosting ? 1 : 0) - this.boostingVisual) * Math.min(1, (dt || 0.016) * 18);
    for (const flame of this.exhaustGlows) {
      const flicker = 0.8 + Math.random() * 0.55;
      flame.material.opacity = this.boostingVisual * 0.9;
      flame.scale.set((1.3 + this.boostingVisual * 2.3) * flicker, (1 + this.boostingVisual * 0.9) * flicker, 1);
    }
    this.boostLight.intensity = this.boostingVisual * 28;

    // ground glow follows car, fades in air
    const active = this.grounded || this.position.y < 4;
    this.groundGlow.material.opacity = (active ? 0.24 : 0.05) + this.boostingVisual * 0.15;
    this.groundGlow.position.set(this.position.x, 0.055, this.position.z);
    this.groundGlow.rotation.z = -this.yaw;
    this.groundGlow.scale.set(6.5 + this.boostingVisual * 2.5, 10 + this.boostingVisual * 3, 1);
    this.groundGlow.material.color.setHex(this.colors.glow).multiplyScalar(1 + this.boostingVisual * 0.7);

    if (this.marker) {
      const t = performance.now() * 0.002;
      this.marker.position.set(this.position.x, this.position.y + 2.2 + Math.sin(t * 2.2) * 0.1, this.position.z);
      this.marker.rotation.y = t * 1.4;
      this.marker.visible = !this.grounded || this.position.y < 5;
    }
  }

  addBoost(amount) {
    const before = this.boost;
    this.boost = Math.min(100, this.boost + amount);
    return this.boost - before;
  }

  bump(nx, nz, power = 1) {
    this.velocity.x += nx * power;
    this.velocity.z += nz * power;
    this.stun = Math.min(0.35, this.stun + 0.08 * power / 10);
  }
}

import * as THREE from 'three';
import { ARENA } from './arena.js';

const DIFF = {
  rookie: { reaction: 0.3, error: 5.5, boostChance: 0.24, lead: 0.24, jump: 0.55, maxThrottle: 0.82 },
  pro: { reaction: 0.13, error: 2.4, boostChance: 0.58, lead: 0.4, jump: 0.78, maxThrottle: 0.96 },
  allstar: { reaction: 0.055, error: 0.85, boostChance: 0.85, lead: 0.52, jump: 0.94, maxThrottle: 1 },
};

function angleDiff(a, b) {
  let d = a - b;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  return d;
}

export class AIController {
  constructor(car, { team, difficulty = 'pro', slot = 0 } = {}) {
    this.car = car;
    this.team = team;
    this.diff = DIFF[difficulty] || DIFF.pro;
    this.slot = slot;
    this.attackDir = team === 'blue' ? 1 : -1;
    this.ownGoal = new THREE.Vector3(team === 'blue' ? -ARENA.halfLength : ARENA.halfLength, 0, 0);
    this.atkGoal = new THREE.Vector3(team === 'blue' ? ARENA.halfLength : -ARENA.halfLength, 0, 0);
    this.target = new THREE.Vector3(0, 0, 0);
    this.thinkTimer = Math.random() * this.diff.reaction;
    this.jumpQueued = false;
    this.noiseSeed = Math.random() * 100;
    this.boostHeld = false;
    this.boostHoldTime = 0;
    this.padTarget = null;
    this.role = slot === 0 ? 'attack' : 'support';
    this.stuckTimer = 0;
    this.lastPos = new THREE.Vector3();
    this.predicted = new THREE.Vector3();
    this.revTimer = 0;
  }

  reset() {
    this.thinkTimer = 0;
    this.jumpQueued = false;
    this.boostHeld = false;
    this.padTarget = null;
    this.stuckTimer = 0;
    this.role = this.slot === 0 ? 'attack' : 'support';
  }

  predictBall(ball, lead = 0.2) {
    const p = this.predicted.copy(ball.position);
    const t = Math.min(1.15, lead);
    p.addScaledVector(ball.velocity, t * 0.78);
    // account for gravity if the ball is airborne
    if (ball.position.y > ARENA.ballRadius + 0.4) {
      p.y += ball.velocity.y * t - 0.5 * 29 * t * t;
      p.y = Math.max(ARENA.ballRadius, p.y);
    }
    p.x = THREE.MathUtils.clamp(p.x, -ARENA.halfLength + 3, ARENA.halfLength - 3);
    p.z = THREE.MathUtils.clamp(p.z, -ARENA.halfWidth + 3, ARENA.halfWidth - 3);
    return p;
  }

  update(dt, world) {
    const car = this.car;
    this.thinkTimer -= dt;
    this.boostHoldTime = Math.max(0, this.boostHoldTime - dt);
    this.revTimer = Math.max(0, this.revTimer - dt);

    const ball = world.ball;
    const teamCars = world.cars.filter(c => c.team === this.team);
    const distToBall = car.position.distanceTo(ball.position);

    // work out whether this AI should attack or hang back
    if (this.thinkTimer <= 0) {
      this.thinkTimer = this.diff.reaction * (0.75 + Math.random() * 0.5);
      const distances = teamCars.map(c => ({ car: c, d: c.position.distanceTo(ball.position) }));
      distances.sort((a, b) => a.d - b.d);
      const myRank = distances.findIndex(o => o.car === car);
      const ballInOwnThird = this.attackDir > 0
        ? ball.position.x < -18
        : ball.position.x > 18;
      const teammateCloser = myRank > 0 && distances[0].d < distToBall - 6;

      if (ballInOwnThird) this.role = 'defend';
      else if (myRank === 0) this.role = 'attack';
      else this.role = teammateCloser ? 'support' : 'attack';

      // choose a boost pad when low and not needed in the play
      if (car.boost < 22 && this.role !== 'attack' && world.pads) {
        let best = null, bestD = 1e9;
        for (const pad of world.pads) {
          if (!pad.active) continue;
          const d = Math.hypot(pad.x - car.position.x, pad.z - car.position.z);
          if (d < bestD && d < 38) { bestD = d; best = pad; }
        }
        if (best && Math.random() < 0.8) this.padTarget = best;
      }
      if (this.padTarget && (!this.padTarget.active || car.boost > 68)) this.padTarget = null;
    }

    const leadT = this.diff.lead * (0.4 + Math.min(1, distToBall / 55));
    const projected = this.predictBall(ball, leadT);

    let tx, tz;
    const goalDir = new THREE.Vector3().subVectors(this.atkGoal, projected).setY(0).normalize();
    const behindDist = 6.3 + Math.min(4, Math.abs(ball.velocity.x) * 0.18);
    const behind = projected.clone().addScaledVector(goalDir, -behindDist);

    if (this.role === 'attack') {
      // line up behind the ball, with a lateral bias to avoid perfect straight lines
      const sideBias = Math.sin(performance.now() * 0.0007 + this.noiseSeed) * 1.8;
      behind.z += sideBias;
      tx = behind.x;
      tz = behind.z;

      // if the ball is high and landing far ahead, meet it at the landing spot
      if (ball.position.y > 5.2 && ball.velocity.y < 1) {
        const vy = ball.velocity.y;
        const dy = ball.position.y - ARENA.ballRadius;
        const t = (vy + Math.sqrt(Math.max(0, vy * vy + 2 * 29 * dy))) / 29;
        if (t < 2.2) {
          tx = ball.position.x + ball.velocity.x * t;
          tz = ball.position.z + ball.velocity.z * t;
          tx = THREE.MathUtils.clamp(tx, -ARENA.halfLength + 4, ARENA.halfLength - 4);
          tz = THREE.MathUtils.clamp(tz, -ARENA.halfWidth + 4, ARENA.halfWidth - 4);
        }
      }
    } else if (this.role === 'defend') {
      // guard the goal: sit on the line between the ball and the net
      const toBall = projected.clone().sub(this.ownGoal).setY(0);
      const d = toBall.length();
      toBall.normalize();
      const depth = Math.min(22, Math.max(8, d * 0.42));
      tx = this.ownGoal.x + toBall.x * depth;
      tz = this.ownGoal.z + toBall.z * depth;
      // near-post shading
      tz += Math.sign(ball.position.z || 1) * 1.2;
    } else {
      // support: stay behind the attacker, ready for a pass or rebound
      tx = behind.x - this.attackDir * 10;
      tz = behind.z + (this.slot % 2 === 0 ? -9 : 9);
    }

    if (this.padTarget) {
      tx = this.padTarget.x;
      tz = this.padTarget.z;
    }

    // add human-like error
    const wobble = performance.now() * 0.0011 + this.noiseSeed;
    tx += Math.sin(wobble * 1.7) * this.diff.error * 0.7;
    tz += Math.cos(wobble * 1.3) * this.diff.error * 0.7;
    tx = THREE.MathUtils.clamp(tx, -ARENA.halfLength + 4, ARENA.halfLength - 4);
    tz = THREE.MathUtils.clamp(tz, -ARENA.halfWidth + 4, ARENA.halfWidth - 4);
    this.target.set(tx, 0, tz);

    const dx = tx - car.position.x;
    const dz = tz - car.position.z;
    const dist = Math.hypot(dx, dz);
    let desiredYaw = Math.atan2(dz, dx);
    let diff = angleDiff(desiredYaw, car.yaw);

    // reverse out of a wall / stuck spot
    const nearWall = Math.abs(car.position.z) > ARENA.halfWidth - 4 || Math.abs(car.position.x) > ARENA.halfLength - 5;
    if (Math.abs(car.speed) < 2.4 && dist > 7) this.stuckTimer += dt;
    else this.stuckTimer = Math.max(0, this.stuckTimer - dt * 2);
    if (this.stuckTimer > 0.75) {
      this.revTimer = 0.65;
      this.stuckTimer = 0;
    }

    let throttle = 1;
    if (Math.abs(diff) > 1.15) throttle = 0.35;
    else if (Math.abs(diff) > 0.55) throttle = 0.7;
    if (dist < 2.2) throttle = 0.15;
    if (this.revTimer > 0) { throttle = -0.7; diff = -diff; }
    throttle *= this.diff.maxThrottle;

    let steer = THREE.MathUtils.clamp(diff * 2.1, -1, 1);
    if (this.revTimer > 0) steer = THREE.MathUtils.clamp(-diff * 2.1, -1, 1);

    // boost management
    const aligned = Math.abs(diff) < 0.22;
    const wantBoost =
      aligned &&
      car.boost > 6 &&
      throttle > 0.5 &&
      (dist > 16 || (this.role === 'attack' && distToBall < 16)) &&
      Math.random() < this.diff.boostChance * dt * 9;
    if (wantBoost) this.boostHoldTime = 0.14 + Math.random() * 0.2;
    let boost = this.boostHoldTime > 0 && car.boost > 1;
    if (!car.grounded && car.boost > 12 && this.role === 'attack' && distToBall < 10) boost = true;

    // jumping at the ball
    this.jumpQueued = false;
    const ballAbove = ball.position.y > 2.8;
    const canReach = distToBall < 8.5;
    if (car.grounded && ballAbove && canReach && Math.random() < this.diff.jump * dt * 6.5) {
      this.jumpQueued = true;
    }
    if (car.grounded && Math.abs(diff) < 0.4 && distToBall < 3.2 && ball.position.y > 4.2) {
      this.jumpQueued = true;
    }
    // double jump toward a high ball
    if (!car.grounded && car.jumps === 1 && car.velocity.y < 2.5 && distToBall < 9 && ball.position.y > car.position.y + 2.2 && Math.random() < this.diff.jump * dt * 4.5) {
      this.jumpQueued = true;
    }

    // air attitude: point roughly at the ball while airborne
    if (!car.grounded) {
      const dy = ball.position.y - car.position.y;
      throttle = THREE.MathUtils.clamp(-dy * 0.08, -1, 1);
      steer = THREE.MathUtils.clamp(diff * 1.5, -1, 1) * 0.7;
      boost = car.boost > 8 && dy > -1;
    }

    if (car.stun > 0) { throttle = 0; steer = 0; boost = false; }

    return {
      throttle,
      steer,
      jump: this.jumpQueued || (!car.grounded && car.jumps === 0),
      jumpPressed: this.jumpQueued,
      boost,
      roll: 0,
      drift: false,
    };
  }

  idle() {
    return { throttle: 0, steer: 0, jump: false, jumpPressed: false, boost: false, roll: 0 };
  }
}

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

import { Arena, ARENA, createEnvironment } from './arena.js';
import { Ball } from './ball.js';
import { Car } from './car.js';
import { AIController } from './ai.js';
import { Effects } from './effects.js';
import { Input } from './input.js';
import { AudioEngine } from './audio.js';

const $ = (id) => document.getElementById(id);
const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
const damp = (current, target, lambda, dt) => current + (target - current) * (1 - Math.exp(-lambda * dt));

function formatClock(seconds) {
  const s = Math.max(0, Math.ceil(seconds));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

class Game {
  constructor() {
    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2(0x040b14, 0.0022);

    this.renderer = new THREE.WebGLRenderer({
      canvas: $('game'),
      antialias: true,
      powerPreference: 'high-performance',
      stencil: false,
    });
    const dpr = Math.min(window.devicePixelRatio || 1, 1.75);
    this.renderer.setPixelRatio(dpr);
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.08;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    this.environment = createEnvironment(this.renderer);
    this.scene.environment = this.environment;
    this.scene.environmentIntensity = 0.58;

    this.camera = new THREE.PerspectiveCamera(62, window.innerWidth / window.innerHeight, 0.1, 550);
    this.camera.position.set(0, 24, 48);
    this.camera.lookAt(0, 4, 0);

    const size = new THREE.Vector2(window.innerWidth, window.innerHeight);
    this.composer = new EffectComposer(this.renderer);
    this.composer.addPass(new RenderPass(this.scene, this.camera));
    this.bloom = new UnrealBloomPass(size, 0.52, 0.62, 0.78);
    this.composer.addPass(this.bloom);
    this.composer.addPass(new OutputPass());

    this.arena = new Arena(this.scene, this.renderer);
    this.effects = new Effects(this.scene, this.renderer);
    this.ball = new Ball(this.scene);
    this.audio = new AudioEngine();
    this.input = new Input();

    this.player = new Car(this.scene, { team: 'blue', isPlayer: true, name: 'YOU', index: 0 });
    this.blueMate = new Car(this.scene, { team: 'blue', isPlayer: false, name: 'NOVA', index: 1 });
    this.orangeA = new Car(this.scene, { team: 'orange', isPlayer: false, name: 'EMBER', index: 2 });
    this.orangeB = new Car(this.scene, { team: 'orange', isPlayer: false, name: 'RAZOR', index: 3 });
    this.cars = [this.player, this.blueMate, this.orangeA, this.orangeB];
    this.aiMap = new Map();

    this.state = 'menu';
    this.mode = '2v2';
    this.difficulty = 'pro';
    this.cinematic = false;
    this.ballCam = true;
    this.time = 180;
    this.overtime = false;
    this.overtimeElapsed = 0;
    this.score = { blue: 0, orange: 0 };
    this.countdown = 3;
    this.lastCountdown = 99;
    this.goalTimer = 0;
    this.endTimer = 0;
    this.shake = 0;
    this.elapsed = 0;
    this.menuAngle = 0.8;
    this.goalCamAngle = 0;
    this.goalSide = 1;
    this.snapCamera = true;
    this.camPos = new THREE.Vector3(0, 24, 48);
    this.camLook = new THREE.Vector3(0, 4, 0);
    this.fov = 62;
    this.playerControls = null;
    this.stats = this._freshStats();
    this.shotCooldown = 0;
    this.saveCooldown = 0;
    this.touchEnabled = window.matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0;
    this.ui = this._uiRefs();

    this._bindHooks();
    this._bindUI();
    this._resize();
    window.addEventListener('resize', () => this._resize());
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && ['playing', 'countdown', 'goal'].includes(this.state)) this.pauseGame();
    });

    this.input.bindTouchControls({
      stickZone: $('stick-zone'),
      knob: $('stick-knob'),
      jumpBtn: $('touch-jump'),
      boostBtn: $('touch-boost'),
    });

    this.returnToMenu(true);
    this._hideLoadingSoon();

    this.last = performance.now();
    this._tick = this._tick.bind(this);
    requestAnimationFrame(this._tick);

    window.__RL3D__ = {
      game: this,
      start: (mode = this.mode, difficulty = this.difficulty) => this.startMatch(mode, difficulty, false),
      cinematic: () => this.startMatch(this.mode, this.difficulty, true),
      menu: () => this.returnToMenu(),
      forceGoal: (side = 1) => {
        this.ball.position.set(side * (ARENA.halfLength - 1), 4, 0);
        this.ball.velocity.set(side * 20, 0, 0);
      },
      state: () => this.state,
    };
  }

  _freshStats() {
    return { goals: 0, shots: 0, saves: 0, boostUsed: 0, topSpeed: 0 };
  }

  _uiRefs() {
    return {
      hud: $('hud'),
      menu: $('menu'),
      help: $('help'),
      pause: $('pause'),
      results: $('results'),
      touch: $('touch'),
      scoreBlue: $('score-blue'),
      scoreOrange: $('score-orange'),
      clock: $('clock'),
      clockLabel: $('clock-label'),
      clockFill: $('clock-fill'),
      boostValue: $('boost-value'),
      boostArc: $('boost-arc'),
      boostHud: $('boost-hud'),
      speed: $('speed'),
      sustaining: $('sustaining'),
      countdown: $('countdown'),
      announce: $('announce'),
      hint: $('hint'),
      toast: $('toast'),
      flash: $('flash'),
      minimap: $('minimap'),
      btnCam: $('btn-cam'),
      btnSound: $('btn-sound'),
      btnSoundMenu: $('btn-sound-menu'),
      resultTitle: $('result-title'),
      resultKicker: $('result-kicker'),
      resultBlue: $('result-blue'),
      resultOrange: $('result-orange'),
      resultStats: $('result-stats'),
      playBtn: $('btn-play'),
      loading: $('loading'),
    };
  }

  _bindHooks() {
    for (const car of this.cars) {
      car.hooks.onBallHit = (who, strength, ball) => {
        ball.lastTouch = who;
        ball.lastTouchAt = this.elapsed;
        this.effects.hit(ball.position, who.team === 'blue' ? 0x54ddff : 0xffa24d, strength);
        this.audio.hit(Math.min(1.8, strength), who.team === 'blue' ? 1.12 : 0.92);
        const dist = who.position.distanceTo(this.player.position);
        if (who === this.player) this.shake = Math.max(this.shake, Math.min(0.55, strength * 0.42));
        else if (dist < 18) this.shake = Math.max(this.shake, Math.min(0.2, strength * 0.12));
        if (who === this.player) {
          this.input.vibrate(14 + Math.round(strength * 20));
          this._trackPlayerTouch(ball);
        }
      };
      car.hooks.onLand = (who, speed) => {
        if (who.position.y <= ARENA.carBaseY + 0.05 && speed > 8) {
          this.effects.burst(
            new THREE.Vector3(who.position.x, 0.15, who.position.z),
            0xa6d9ee, Math.min(14, Math.round(speed / 4)), 3.5, 0.55, 0.5, 4
          );
          if (who === this.player) this.shake = Math.max(this.shake, Math.min(0.18, speed / 300));
        }
      };
      car.hooks.onJump = (who) => {
        this.audio.jump();
      };
      car.hooks.onFlip = (who) => {
        this.effects.burst(who.position, 0xffffff, 8, 4, 0.4, 0.35, 0);
      };
    }

    this.ball.onImpact = (strength, pos) => {
      this.effects.hit(pos, 0x9feaff, Math.min(1.2, strength));
      this.audio.hit(strength * 0.6, 1.35);
      if (strength > 0.55) this.shake = Math.max(this.shake, Math.min(0.22, strength * 0.18));
    };

    this.ball.onGoal = (side, pos) => this.onGoal(side, pos);
  }

  _bindUI() {
    const click = (fn) => (e) => { e.preventDefault(); this.audio.init(); this.audio.click(); fn(); };

    $('btn-play').addEventListener('click', click(() => this.startMatch(this.mode, this.difficulty, false)));
    $('btn-spectate').addEventListener('click', click(() => this.startMatch(this.mode, this.difficulty, true)));
    $('btn-help').addEventListener('click', click(() => this._showHelp(true)));
    $('btn-help-close').addEventListener('click', click(() => this._showHelp(false)));
    $('btn-help-play').addEventListener('click', click(() => { this._showHelp(false); this.startMatch(this.mode, this.difficulty, false); }));

    $('btn-sound').addEventListener('click', click(() => this.toggleSound()));
    $('btn-sound-menu').addEventListener('click', click(() => this.toggleSound()));
    $('btn-cam').addEventListener('click', click(() => this.toggleBallCam()));
    $('btn-pause')?.addEventListener('click', click(() => this.pauseGame()));

    $('btn-resume').addEventListener('click', click(() => this.resumeGame()));
    $('btn-restart').addEventListener('click', click(() => this.startMatch(this.mode, this.difficulty, this.cinematic)));
    $('btn-quit').addEventListener('click', click(() => this.returnToMenu()));

    $('btn-again').addEventListener('click', click(() => this.startMatch(this.mode, this.difficulty, this.cinematic)));
    $('btn-menu').addEventListener('click', click(() => this.returnToMenu()));

    for (const btn of document.querySelectorAll('#mode-select .seg')) {
      btn.addEventListener('click', click(() => {
        this.mode = btn.dataset.mode;
        for (const b of document.querySelectorAll('#mode-select .seg')) b.classList.toggle('active', b === btn);
        this._updatePlayLabel();
      }));
    }
    for (const btn of document.querySelectorAll('#diff-select .seg')) {
      btn.addEventListener('click', click(() => {
        this.difficulty = btn.dataset.diff;
        for (const b of document.querySelectorAll('#diff-select .seg')) b.classList.toggle('active', b === btn);
      }));
    }

    $('stick-zone').addEventListener('pointerdown', () => this.audio.init(), { passive: true });
    document.addEventListener('pointerdown', () => this.audio.init(), { once: true });
  }

  _updatePlayLabel() {
    const small = this.ui.playBtn?.querySelector('.play-text small');
    if (small) small.textContent = `${this.mode.toUpperCase()} · ${this.difficulty === 'allstar' ? 'ALL-STAR' : this.difficulty.toUpperCase()}`;
  }

  _showHelp(show) {
    this.ui.help.classList.toggle('hidden', !show);
    if (show) this.ui.menu.classList.add('hidden');
    else if (this.state === 'menu') this.ui.menu.classList.remove('hidden');
  }

  toggleSound() {
    this.audio.init();
    this.audio.setEnabled(!this.audio.enabled);
    const on = this.audio.enabled;
    for (const btn of [this.ui.btnSound, this.ui.btnSoundMenu]) {
      if (btn) btn.classList.toggle('muted', !on);
    }
    this._toast(on ? 'SOUND ON' : 'SOUND OFF');
  }

  toggleBallCam() {
    this.ballCam = !this.ballCam;
    this.ui.btnCam.classList.toggle('on', this.ballCam);
    this._toast(this.ballCam ? 'BALL CAM ON' : 'BALL CAM OFF');
  }

  _toast(text, duration = 1.4) {
    const el = this.ui.toast;
    el.textContent = text;
    el.classList.add('on');
    clearTimeout(this._toastTimer);
    this._toastTimer = setTimeout(() => el.classList.remove('on'), duration * 1000);
  }

  _hideLoadingSoon() {
    const finish = () => {
      this.ui.loading.classList.add('done');
      setTimeout(() => this.ui.loading.remove(), 700);
    };
    if (document.fonts?.ready) document.fonts.ready.then(() => setTimeout(finish, 120));
    else setTimeout(finish, 400);
  }

  _resize() {
    const w = window.innerWidth, h = window.innerHeight;
    const portrait = w / h < 0.82;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, portrait ? 1.6 : 1.75));
    this.renderer.setSize(w, h);
    this.composer.setSize(w, h);
    this.bloom.resolution.set(w, h);
    this.camera.aspect = w / h;
    this.camera.fov = portrait ? 72 : 62;
    this.camera.updateProjectionMatrix();
    this.effects.points.material.uniforms.uPixelRatio.value = Math.min(2, this.renderer.getPixelRatio());
  }

  returnToMenu(initial = false) {
    this.state = 'menu';
    this.cinematic = false;
    this.ui.menu.classList.remove('hidden');
    this.ui.help.classList.add('hidden');
    this.ui.pause.classList.add('hidden');
    this.ui.results.classList.add('hidden');
    this.ui.hud.classList.add('hidden');
    this.ui.touch.classList.add('hidden');
    this.ui.countdown.classList.add('hidden');
    this.ui.announce.classList.add('hidden');
    this.ui.btnCam.classList.toggle('on', this.ballCam);
    this.audio.setScene('menu');
    this.effects.reset();
    this.ball.reset(0, ARENA.ballRadius, 0);
    this.ball.mesh.visible = true;
    this.ball.glow.visible = true;
    this.ball.light.visible = true;

    const preview = [
      [-21, 9, 0.05], [-31, -10, 0.28], [21, -9, Math.PI + 0.06], [31, 10, Math.PI - 0.25],
    ];
    this.cars.forEach((car, i) => {
      car.active = true;
      car.root.visible = true;
      car.groundGlow.visible = true;
      if (car.marker) car.marker.visible = true;
      car.reset(preview[i][0], preview[i][1], preview[i][2]);
      car.boost = 33;
    });
    this.snapCamera = true;
    this.menuAngle = initial ? 0.85 : 0.6;
    document.body.dataset.state = 'menu';
    this._updatePlayLabel();
  }

  startMatch(mode = this.mode, difficulty = this.difficulty, cinematic = false) {
    this.audio.init();
    this.audio.setScene('game');
    this.mode = mode;
    this.difficulty = difficulty;
    this.cinematic = cinematic;
    this.state = 'countdown';
    this.time = 180;
    this.overtime = false;
    this.overtimeElapsed = 0;
    this.score = { blue: 0, orange: 0 };
    this.countdown = 3.15;
    this.lastCountdown = 99;
    this.goalTimer = 0;
    this.endTimer = 0;
    this.shake = 0;
    this.stats = this._freshStats();
    this.shotCooldown = 0;
    this.saveCooldown = 0;
    this.ball.scoredAgainst = 0;
    this.effects.reset();

    this.ui.menu.classList.add('hidden');
    this.ui.help.classList.add('hidden');
    this.ui.results.classList.add('hidden');
    this.ui.pause.classList.add('hidden');
    this.ui.hud.classList.remove('hidden');
    this.ui.hint.style.opacity = '1';
    this.ui.hint.classList.remove('hidden');
    this.ui.countdown.classList.add('hidden');
    this.ui.announce.classList.add('hidden');
    this.ui.btnCam.classList.toggle('on', this.ballCam);
    this.ui.touch.classList.toggle('hidden', !this.touchEnabled || cinematic);
    document.body.dataset.state = 'playing';

    const active = mode === '2v2' ? this.cars : [this.player, this.orangeA];
    for (const car of this.cars) {
      const on = active.includes(car);
      car.active = on;
      car.root.visible = on;
      car.groundGlow.visible = on;
      if (car.marker) car.marker.visible = on;
    }

    this._buildAIs(active);
    this.resetKickoff();
    this._updatePlayLabel();
    this._updateScoreboard(true);
    this.snapCamera = true;
    if (cinematic) {
      this._toast('CINEMATIC · ESC TO EXIT', 2.4);
    }
  }

  _buildAIs(active) {
    this.aiMap.clear();
    const mk = (car, slot) => new AIController(car, { team: car.team, difficulty: this.difficulty, slot });
    for (const car of active) {
      if (car.isPlayer) continue;
      this.aiMap.set(car, mk(car, car.index));
    }
    if (this.cinematic) this.playerAI = new AIController(this.player, { team: 'blue', difficulty: this.difficulty, slot: 0 });
    else this.playerAI = null;
  }

  resetKickoff() {
    this.ball.reset(0, ARENA.ballRadius, 0, true);
    this.ball.scoredAgainst = 0;
    if (this.mode === '1v1') {
      this.player.reset(-30, 0, 0);
      this.orangeA.reset(30, 0, Math.PI);
    } else {
      this.player.reset(-30, 0, 0);
      this.blueMate.reset(-39, -12, 0.08);
      this.orangeA.reset(30, 0, Math.PI);
      this.orangeB.reset(39, 12, Math.PI - 0.08);
    }
    for (const ai of this.aiMap.values()) ai.reset();
    this.playerAI?.reset();
    this.goalCamAngle = 0;
    this.snapCamera = true;
  }

  pauseGame() {
    if (!['playing', 'countdown', 'goal', 'ending'].includes(this.state)) return;
    this.pausedFrom = this.state;
    this.state = 'paused';
    this.ui.pause.classList.remove('hidden');
    this.ui.touch.classList.add('hidden');
    document.body.dataset.state = 'paused';
  }

  resumeGame() {
    if (this.state !== 'paused') return;
    this.state = this.pausedFrom || 'playing';
    this.ui.pause.classList.add('hidden');
    this.ui.touch.classList.toggle('hidden', !this.touchEnabled || this.cinematic);
    document.body.dataset.state = 'playing';
    this.last = performance.now();
  }

  onGoal(side, pos) {
    if (this.state !== 'playing') return;
    const scoring = side > 0 ? 'blue' : 'orange';
    this.score[scoring]++;
    this.state = 'goal';
    this.goalTimer = 3.1;
    this.goalSide = side;
    this.goalCamAngle = 0;
    this.shake = 1.25;
    this.snapCamera = false;

    const teamColor = scoring === 'blue' ? 0x2ed2ff : 0xff8a2e;
    this.effects.goalExplosion(new THREE.Vector3(side * (ARENA.halfLength + 3), 6.5, 0), teamColor);
    this.arena.goalFlash(side, 1);
    this.audio.goal();
    this.input.vibrate(220);
    this._flash();

    const last = this.ball.lastTouch;
    if (scoring === 'blue' && last === this.player) this.stats.goals++;
    this.ball.lastTouch = null;

    const kicks = ['BACK OF THE NET', 'TOP SHELF', 'ABSOLUTE ROCKET', 'WHAT A STRIKE', 'UNSTOPPABLE'];
    this._showAnnounce(kicks[Math.floor(Math.random() * kicks.length)], `${scoring.toUpperCase()} SCORES`, `${this.score.blue}  —  ${this.score.orange}`, scoring, 3.1);
    this._updateScoreboard(true);
    this.ui.hint.classList.add('hidden');
    this._updateScoreboard(true);
  }

  afterGoal() {
    if (this.overtime) {
      this.endMatch();
      return;
    }
    if (this.time <= 0) {
      this.endMatch();
      return;
    }
    this.resetKickoff();
    this.state = 'countdown';
    this.countdown = 2.7;
    this.lastCountdown = 99;
    this.ball.scoredAgainst = 0;
    this.ui.announce.classList.add('hidden');
    this.ui.hint.classList.add('hidden');
  }

  startOvertime() {
    this.overtime = true;
    this.time = 0;
    this.overtimeElapsed = 0;
    this.resetKickoff();
    this.state = 'countdown';
    this.countdown = 3.15;
    this.lastCountdown = 99;
    this._showAnnounce('SUDDEN DEATH', 'OVERTIME', 'NEXT GOAL WINS', 'gold', 2.6);
    this.audio.whistle();
  }

  beginEnding() {
    this.state = 'ending';
    this.endTimer = 1.25;
    this.ui.countdown.classList.add('hidden');
    this._showAnnounce('FULL TIME', 'MATCH COMPLETE', '', '', 1.3);
    this.audio.whistle();
  }

  endMatch() {
    this.state = 'ended';
    this.ui.announce.classList.add('hidden');
    this.ui.countdown.classList.add('hidden');
    this.ui.touch.classList.add('hidden');
    this.ui.hud.classList.add('hidden');
    this.ui.results.classList.remove('hidden');
    this.audio.setScene('menu');
    const blueWins = this.score.blue > this.score.orange;
    const tie = this.score.blue === this.score.orange;
    this.ui.resultKicker.textContent = this.overtime ? 'OVERTIME WINNER' : 'FULL TIME';
    this.ui.resultTitle.textContent = tie ? 'DRAW' : blueWins ? 'BLUE WINS' : 'ORANGE WINS';
    this.ui.resultTitle.classList.toggle('lose', !blueWins && !tie);
    this.ui.resultBlue.textContent = this.score.blue;
    this.ui.resultOrange.textContent = this.score.orange;
    const s = this.stats;
    this.ui.resultStats.innerHTML = [
      [s.goals, 'YOUR GOALS'],
      [s.shots, 'SHOTS'],
      [s.saves, 'SAVES'],
      [Math.round(s.topSpeed), 'TOP KM/H'],
    ].map(([v, l]) => `<div><b>${v}</b><span>${l}</span></div>`).join('');
    document.body.dataset.state = 'ended';
    this._updateScoreboard(true);
  }

  _updatePlayLabel() {
    const small = this.ui.playBtn?.querySelector('.play-text small');
    if (small) small.textContent = `${this.mode.toUpperCase()} · ${this.difficulty === 'allstar' ? 'ALL-STAR' : this.difficulty.toUpperCase()}`;
  }

  _trackPlayerTouch(ball) {
    // shot on goal?
    if (this.shotCooldown <= 0 && ball.velocity.x > 22 && ball.position.x > -34) {
      this.stats.shots++;
      this.shotCooldown = 0.5;
    }
    // goal-line clearance
    if (this.saveCooldown <= 0 && ball.position.x < -38 && ball.velocity.x > 6) {
      this.stats.saves++;
      this.saveCooldown = 1.2;
      this._toast('SAVE!');
    }
  }

  _flash() {
    this.ui.flash.classList.add('on');
    setTimeout(() => this.ui.flash.classList.remove('on'), 40);
  }

  _showAnnounce(kicker, main, sub, cls = '', duration = 2.2) {
    const el = this.ui.announce;
    el.className = `announce ${cls}`;
    el.querySelector('.announce-kicker').textContent = kicker;
    const mainEl = el.querySelector('.announce-main');
    mainEl.textContent = main;
    mainEl.style.animation = 'none';
    void mainEl.offsetWidth;
    mainEl.style.animation = '';
    el.querySelector('.announce-sub').textContent = sub;
    el.classList.remove('hidden');
    clearTimeout(this._announceTimer);
    this._announceTimer = setTimeout(() => el.classList.add('hidden'), duration * 1000);
  }

  _showCountdown(text, go = false) {
    const el = this.ui.countdown;
    el.classList.remove('hidden');
    el.classList.toggle('go', go);
    const span = el.querySelector('span');
    span.textContent = text;
    span.style.animation = 'none';
    void span.offsetWidth;
    span.style.animation = '';
    clearTimeout(this._countdownTimer);
    this._countdownTimer = setTimeout(() => el.classList.add('hidden'), go ? 950 : 1000);
  }

  _updateScoreboard(force = false) {
    const b = this.score.blue, o = this.score.orange;
    this.ui.scoreBlue.textContent = b;
    this.ui.scoreOrange.textContent = o;
    const label = this.overtime ? 'OVERTIME' : 'REGULATION';
    const clock = this.overtime ? formatClock(this.overtimeElapsed) : formatClock(this.time);
    this.ui.clock.textContent = clock;
    this.ui.clockLabel.textContent = label;
    this.ui.clock.classList.toggle('urgent', !this.overtime && this.time <= 15.2 && this.state === 'playing');
    const fill = this.overtime ? 100 : clamp((this.time / 180) * 100, 0, 100);
    this.ui.clockFill.style.width = `${fill}%`;
    this.arena.setScore(b, o, clock, label);
  }

  _updateHUD(dt) {
    if (this.state === 'menu') return;
    this._updateScoreboard();
    const car = this.player;
    const boost = Math.round(car.boost);
    this.ui.boostValue.textContent = boost;
    const arc = 264;
    this.ui.boostArc.style.strokeDashoffset = String(arc * (1 - clamp(boost, 0, 100) / 100));
    this.ui.boostHud.classList.toggle('low', boost < 20);
    const displaySpeed = Math.round(car.speed * 4.05);
    this.ui.speed.textContent = String(displaySpeed).padStart(3, '0');
    this.ui.sustaining.classList.toggle('on', car.speed > 49);
    this._drawMinimap();
  }

  _drawMinimap() {
    const cv = this.ui.minimap;
    const ctx = cv.getContext('2d');
    const W = cv.width, H = cv.height;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = 'rgba(4, 16, 29, 0.72)';
    ctx.fillRect(0, 0, W, H);
    const pad = 12;
    const mapX = (x) => pad + ((x + ARENA.halfLength) / ARENA.length) * (W - pad * 2);
    const mapZ = (z) => pad + ((z + ARENA.halfWidth) / ARENA.width) * (H - pad * 2);

    // pitch
    ctx.fillStyle = 'rgba(15, 61, 58, 0.7)';
    ctx.fillRect(mapX(-54), mapZ(-35), mapX(54) - mapX(-54), mapZ(35) - mapZ(-35));
    ctx.strokeStyle = 'rgba(160, 245, 255, 0.55)';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(mapX(-54), mapZ(-35), mapX(54) - mapX(-54), mapZ(35) - mapZ(-35));
    ctx.beginPath();
    ctx.moveTo(mapX(0), mapZ(-35));
    ctx.lineTo(mapX(0), mapZ(35));
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(mapX(0), mapZ(0), 13, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(160, 245, 255, 0.24)';
    ctx.stroke();

    // goals
    const gh = mapZ(13) - mapZ(-13);
    ctx.fillStyle = 'rgba(35, 200, 255, 0.5)';
    ctx.fillRect(mapX(-60) - 2, mapZ(-13), 4, gh);
    ctx.fillStyle = 'rgba(255, 122, 24, 0.5)';
    ctx.fillRect(mapX(60) - 2, mapZ(-13), 4, gh);

    // boost pads
    for (const p of this.arena.pads) {
      if (!p.active) continue;
      ctx.fillStyle = p.big ? 'rgba(255, 190, 40, 0.95)' : 'rgba(255, 220, 100, 0.6)';
      ctx.beginPath();
      ctx.arc(mapX(p.x), mapZ(p.z), p.big ? 3.2 : 1.8, 0, Math.PI * 2);
      ctx.fill();
    }

    // cars
    for (const car of this.cars) {
      if (!car.active) continue;
      if (car === this.player) continue;
      const x = mapX(car.position.x), y = mapZ(car.position.z);
      ctx.fillStyle = car.team === 'blue' ? 'rgba(60, 210, 255, 0.85)' : 'rgba(255, 135, 40, 0.9)';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    }

    // ball
    const bx = mapX(this.ball.position.x), by = mapZ(this.ball.position.z);
    ctx.shadowColor = '#8ef2ff';
    ctx.shadowBlur = 9;
    ctx.fillStyle = '#e8fdff';
    ctx.beginPath();
    ctx.arc(bx, by, 3.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    // player arrow
    const px = mapX(this.player.position.x), py = mapZ(this.player.position.z);
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(this.player.yaw);
    ctx.fillStyle = '#ffe17a';
    ctx.shadowColor = '#ffd257';
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.moveTo(7.5, 0);
    ctx.lineTo(-4.5, 5);
    ctx.lineTo(-2, 0);
    ctx.lineTo(-4.5, -5);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  _updateCars(dt, idle = false) {
    const world = { ball: this.ball, cars: this.cars.filter(c => c.active), pads: this.arena.pads };
    const playerAi = this.cinematic || idle ? this.playerAI : null;
    for (const car of this.cars) {
      if (!car.active) continue;
      let controls;
      if (car.isPlayer) {
        if (this.cinematic && this.playerAI) controls = this.playerAI.update(dt, world);
        else if (idle) controls = this.aiMap.get(car)?.idle() || { throttle: 0, steer: 0, jump: false, jumpPressed: false, boost: false, roll: 0 };
        else controls = this.playerControls || { throttle: 0, steer: 0, jump: false, jumpPressed: false, boost: false, roll: 0 };
      } else {
        const ai = this.aiMap.get(car);
        controls = idle ? ai.idle() : ai.update(dt, world);
      }
      car.update(dt, controls, world);
    }
    if (!idle) this._collectPads();
  }

  _collectPads() {
    for (const car of this.cars) {
      if (!car.active || car.position.y > 4) continue;
      for (const pad of this.arena.pads) {
        if (!pad.active) continue;
        const d = Math.hypot(car.position.x - pad.x, car.position.z - pad.z);
        if (d < pad.radius) {
          const amount = this.arena.takePad(pad);
          car.addBoost(amount);
          this.audio.boostPad(pad.big);
          this.effects.burst(
            new THREE.Vector3(pad.x, 1.1, pad.z),
            pad.big ? 0xffb01e : 0xffe27a,
            pad.big ? 24 : 9, 8, 0.7, 0.6, 4
          );
          if (car === this.player && pad.big) this.input.vibrate(18);
        }
      }
    }
  }

  _resolveCarCollisions() {
    const active = this.cars.filter(c => c.active);
    for (let i = 0; i < active.length; i++) {
      for (let j = i + 1; j < active.length; j++) {
        const a = active[i], b = active[j];
        const dx = a.position.x - b.position.x;
        const dz = a.position.z - b.position.z;
        const dist = Math.hypot(dx, dz);
        const min = 2.55;
        if (dist > 0.0001 && dist < min) {
          const nx = dx / dist, nz = dz / dist;
          const overlap = min - dist;
          a.position.x += nx * overlap * 0.5;
          a.position.z += nz * overlap * 0.5;
          b.position.x -= nx * overlap * 0.5;
          b.position.z -= nz * overlap * 0.5;
          const rel = (a.velocity.x - b.velocity.x) * nx + (a.velocity.z - b.velocity.z) * nz;
          if (rel < 0) {
            const impulse = Math.min(11, -rel * 0.62);
            a.velocity.x += nx * impulse;
            a.velocity.z += nz * impulse;
            b.velocity.x -= nx * impulse;
            b.velocity.z -= nz * impulse;
            const contact = new THREE.Vector3((a.position.x + b.position.x) / 2, 1.0, (a.position.z + b.position.z) / 2);
            this.effects.hit(contact, 0xffe0a8, Math.min(1.4, -rel / 16));
            if (a === this.player || b === this.player) {
              this.shake = Math.max(this.shake, Math.min(0.3, -rel / 90));
              this.input.vibrate(24);
            }
            this.audio.hit(Math.min(1.2, -rel / 30), 0.7);
          }
        }
      }
    }
  }

  _updateMatch(dt) {
    this.shotCooldown = Math.max(0, this.shotCooldown - dt);
    this.saveCooldown = Math.max(0, this.saveCooldown - dt);

    if (this.state === 'countdown') {
      this.countdown -= dt;
      const n = Math.ceil(this.countdown);
      if (n > 0 && n !== this.lastCountdown) {
        this.lastCountdown = n;
        this._showCountdown(String(n));
        this.audio.beep(n === 1);
      }
      this.ball.update(dt, this.effects);
      if (this.countdown <= 0) {
        this.state = 'playing';
        this._showCountdown('GO!', true);
        this.audio.beep(true);
        this._updateScoreboard(true);
      }
      return;
    }

    if (this.state === 'playing') {
      this._updateCars(dt, false);
      this.ball.update(dt, this.effects);
      this._resolveCarCollisions();
      if (this.state === 'playing') {
        if (this.overtime) this.overtimeElapsed += dt;
        else this.time = Math.max(0, this.time - dt);
        if (!this.overtime && this.time <= 0) {
          if (this.score.blue === this.score.orange) this.startOvertime();
          else this.beginEnding();
        }
      } else if (this.state === 'goal') {
        if (this.overtime) this.overtimeElapsed += dt;
        else this.time = Math.max(0, this.time - dt);
      }
      if (this.player.boosting) this.stats.boostUsed += 33 * dt;
      this.stats.topSpeed = Math.max(this.stats.topSpeed, this.player.speed * 4.05);
      return;
    }

    if (this.state === 'goal') {
      this._updateCars(dt, true);
      this.ball.update(dt, this.effects);
      this._resolveCarCollisions();
      if (this.overtime) this.overtimeElapsed += dt;
      else this.time = Math.max(0, this.time - dt);
      this.goalTimer -= dt;
      if (this.goalTimer <= 0) this.afterGoal();
      return;
    }

    if (this.state === 'ending') {
      this.ball.update(dt, this.effects);
      this.endTimer -= dt;
      if (this.endTimer <= 0) this.endMatch();
    }
  }

  _updateMenu(dt) {
    this.ball.update(dt, null);
    // cars are parked, but their suspension and boost glow still breathe
    for (const car of this.cars) car._syncVisuals(dt, 0);
    this.menuAngle += dt * 0.055;
  }

  _updateCamera(dt) {
    const cam = this.camera;
    let targetFov = window.innerWidth / window.innerHeight < 0.82 ? 72 : 62;
    const desiredPos = new THREE.Vector3();
    const desiredLook = new THREE.Vector3();

    if (this.state === 'menu') {
      const a = this.menuAngle;
      desiredPos.set(Math.cos(a) * 48, 22 + Math.sin(a * 0.7) * 3.5, Math.sin(a) * 48);
      desiredLook.set(0, 5.2, 0);
    } else if (this.cinematic && !['goal', 'ended'].includes(this.state)) {
      this.menuAngle += dt * 0.14;
      const a = this.menuAngle;
      const center = this.ball.position;
      desiredPos.set(center.x * 0.35 + Math.cos(a) * 41, 18 + Math.sin(a * 0.8) * 4, center.z * 0.4 + Math.sin(a) * 41);
      desiredLook.copy(center).lerp(this.player.position, 0.18);
      desiredLook.y += 2;
    } else if (this.state === 'goal' || (this.state === 'ended' && this.score.blue === this.score.orange)) {
      this.goalCamAngle += dt * 0.55;
      const center = this.ball.position;
      const a = this.goalCamAngle;
      desiredPos.set(center.x + Math.cos(a) * 17, 8.5 + Math.sin(a * 0.8) * 2.2, center.z + Math.sin(a) * 20);
      desiredLook.copy(center);
      desiredLook.y += 3;
    } else if (this.state === 'ended') {
      this.menuAngle += dt * 0.1;
      desiredPos.set(Math.cos(this.menuAngle) * 46, 21, Math.sin(this.menuAngle) * 46);
      desiredLook.set(0, 5, 0);
    } else {
      const car = this.player;
      const ball = this.ball.position;
      const fwd = new THREE.Vector3(1, 0, 0).applyQuaternion(car.quaternion);
      fwd.y = 0;
      if (fwd.lengthSq() < 0.01) fwd.set(1, 0, 0);
      fwd.normalize();
      const toBall = new THREE.Vector3(ball.x - car.position.x, 0, ball.z - car.position.z);
      const ballDist = toBall.length();
      const dir = ballDist > 2 ? toBall.normalize() : fwd.clone();
      const speed = car.speed;
      if (this.ballCam) {
        const back = 15.2 + Math.min(6.5, speed * 0.11) + (car.boosting ? 1.6 : 0);
        desiredPos.copy(car.position).addScaledVector(dir, -back);
        desiredPos.y = 7.2 + Math.min(4.5, Math.max(0, ball.y - 2) * 0.18) + (car.boosting ? 0.6 : 0);
        desiredLook.copy(car.position).addScaledVector(dir, 5.5);
        desiredLook.y += 1.9;
        const ballLook = new THREE.Vector3(ball.x, ball.y * 0.6 + 2.1, ball.z);
        desiredLook.lerp(ballLook, 0.46);
        targetFov += Math.min(11, speed * 0.18) + (car.boosting ? 4.5 : 0);
      } else {
        desiredPos.copy(car.position).addScaledVector(fwd, -17.5);
        desiredPos.y = 7.6;
        desiredLook.copy(car.position).addScaledVector(fwd, 8);
        desiredLook.y += 2.2;
        targetFov += Math.min(9, speed * 0.14);
      }
    }

    desiredPos.x = clamp(desiredPos.x, -57.6, 57.6);
    desiredPos.z = clamp(desiredPos.z, -37.6, 37.6);
    desiredPos.y = clamp(desiredPos.y, 2.1, 27.5);

    if (this.snapCamera) {
      this.camPos.copy(desiredPos);
      this.camLook.copy(desiredLook);
      this.snapCamera = false;
    } else {
      const posL = this.state === 'menu' ? 2.1 : 7.5;
      const lookL = this.state === 'menu' ? 2.8 : 9.5;
      this.camPos.x = damp(this.camPos.x, desiredPos.x, posL, dt);
      this.camPos.y = damp(this.camPos.y, desiredPos.y, posL, dt);
      this.camPos.z = damp(this.camPos.z, desiredPos.z, posL, dt);
      this.camLook.x = damp(this.camLook.x, desiredLook.x, lookL, dt);
      this.camLook.y = damp(this.camLook.y, desiredLook.y, lookL, dt);
      this.camLook.z = damp(this.camLook.z, desiredLook.z, lookL, dt);
    }

    this.shake = Math.max(0, this.shake - dt * 2.2);
    const shake = this.shake * this.shake;
    const sx = (Math.random() - 0.5) * shake * 0.9;
    const sy = (Math.random() - 0.5) * shake * 0.7;
    const sz = (Math.random() - 0.5) * shake * 0.9;
    cam.position.copy(this.camPos);
    cam.position.x += sx;
    cam.position.y += sy;
    cam.position.z += sz;
    cam.lookAt(this.camLook.x + sx * 0.4, this.camLook.y + sy * 0.4, this.camLook.z + sz * 0.4);

    this.fov = damp(this.fov, targetFov, 4, dt);
    cam.fov = this.fov;
    cam.updateProjectionMatrix();
    this.effects.setCameraQuat(cam.quaternion);
  }

  _tick(now) {
    requestAnimationFrame(this._tick);
    const raw = (now - this.last) / 1000;
    this.last = now;
    const dt = clamp(raw || 0, 0.001, 0.05);
    this.elapsed += dt;

    this.playerControls = this.input.poll();

    if (this.input.wasPressed('sound')) this.toggleSound();
    if (this.input.wasPressed('ballcam')) this.toggleBallCam();
    if (this.input.wasPressed('pause')) {
      if (this.state === 'paused') this.resumeGame();
      else if (['playing', 'countdown', 'goal', 'ending'].includes(this.state)) this.pauseGame();
      else if (this.state === 'menu') this._showHelp(false);
      else if (this.state === 'ended') this.returnToMenu();
    }

    if (this.state === 'menu') {
      this._updateMenu(dt);
    } else if (this.state === 'paused') {
      // keep the world still, but idle camera breathing is fine
    } else {
      this._updateMatch(dt);
    }

    this.arena.update(dt, this.elapsed, this.ball.position);
    this.effects.update(dt);
    this._updateCamera(dt);
    this._updateHUD(dt);

    // fade the control hint after the first few seconds of a match
    if (['playing', 'goal'].includes(this.state) && this.elapsed > 9 && this.ui.hint.style.opacity !== '0') {
      this.ui.hint.style.opacity = '0';
    }

    this.composer.render();
    this.input.endFrame();
  }
}

window.addEventListener('DOMContentLoaded', () => {
  try {
    new Game();
    window.__RL_READY__ = true;
    document.body.dataset.ready = '1';
  } catch (error) {
    console.error(error);
    const loading = document.getElementById('loading');
    if (loading) {
      loading.innerHTML = `<div class="loading-text" style="max-width:420px;text-align:center;line-height:1.8">ARENA FAILED TO LOAD<br><span style="font-family:Rajdhani;font-size:11px;letter-spacing:.5px;color:#7096ab">${String(error.message || error)}</span></div>`;
    }
  }
});

