import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
const errors = [];
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
page.on('pageerror', e => { console.log('PAGEERROR', e.stack); errors.push(e.message); });
page.on('response', r => { if (r.status() >= 400) console.log('HTTP', r.status(), r.url()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1800);
await page.click('#btn-play');
await page.waitForTimeout(4000);
console.log(await page.evaluate(() => {
  const g = window.__RL3D__.game;
  return { state: g.state, time: g.time, score: g.score, ball: g.ball.position.toArray().map(n=>+n.toFixed(1)), player: g.player.position.toArray().map(n=>+n.toFixed(1)), speed: +g.player.speed.toFixed(1), aiPositions: g.cars.slice(1).map(c=>c.position.toArray().map(n=>+n.toFixed(1))) };
}));
await page.screenshot({ path: '/tmp/opencode/shots/game.png' });
await page.keyboard.down('KeyW');
await page.keyboard.down('ShiftLeft');
await page.waitForTimeout(1800);
await page.keyboard.up('ShiftLeft');
await page.keyboard.up('KeyW');
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/shots/game-driving.png' });
console.log('after drive', await page.evaluate(() => { const g=window.__RL3D__.game; return {state:g.state, ball:g.ball.position.toArray().map(n=>+n.toFixed(1)), player:g.player.position.toArray().map(n=>+n.toFixed(1)), speed:+g.player.speed.toFixed(1), boost:+g.player.boost.toFixed(1), score:g.score}; }));
console.log('errors', errors.length);
await browser.close();

