513:   _collideBall(ball) {
514:     const qInv = this._tmp.q1.copy(this.quaternion).invert();
515:     const local = this._tmp.v1.copy(ball.position).sub(this.position).applyQuaternion(qInv);
516:     // chassis half-extents (slightly forgiving)
517:     const hx = 2.22, hy = 0.52, hz = 1.06;
518:     const cx = Math.max(-hx, Math.min(hx, local.x));
519:     const cy = Math.max(-hy, Math.min(hy, local.y));
520:     const cz = Math.max(-hz, Math.min(hz, local.z));
521:     const dx = local.x - cx, dy = local.y - cy, dz = local.z - cz;
522:     const distSq = dx * dx + dy * dy + dz * dz;
523:     const r = ball.radius;
524:     if (distSq > r * r) return;
525: 
526:     let dist = Math.sqrt(distSq);
527:     let nx, ny, nz;
528:     if (dist < 0.0001) {
529:       // deep overlap: push out through nearest face
530:       const px = hx - Math.abs(local.x);
531:       const py = hy - Math.abs(local.y);
532:       const pz = hz - Math.abs(local.z);
533:       if (px < py && px < pz) { nx = Math.sign(local.x) || 1; ny = 0; nz = 0; dist = 0; }
534:       else if (py < pz) { nx = 0; ny = Math.sign(local.y) || 1; nz = 0; dist = 0; }
535:       else { nx = 0; ny = 0; nz = Math.sign(local.z) || 1; dist = 0; }
536:     } else {
537:       nx = dx / dist; ny = dy / dist; nz = dz / dist;
538:     }
539: 
540:     const normal = this._tmp.v2.set(nx, ny, nz).applyQuaternion(this.quaternion).normalize();
541:     const pen = r - dist;
542:     ball.position.addScaledVector(normal, pen + 0.02);
543: 
544:     const rel = this._tmp.v3.copy(ball.velocity).sub(this.velocity);
545:     const vn = rel.dot(normal);
546:     const carSpeed = this.velocity.length();
547: 
548:     if (this.hitCooldown <= 0) {
549:       let strength = 0;
550:       if (vn < 0) {
551:         const e = 0.62;
552:         const impulse = -(1 + e) * vn * 0.96; // ball mass 1, car effectively much heavier
553:         ball.velocity.addScaledVector(normal, impulse);
554:         strength = Math.min(2.2, Math.abs(vn) / 18 + carSpeed / 45);
555:       }
556:       // transfer momentum from the car's motion into the ball
557:       const carAlong = Math.max(0, this.velocity.dot(normal));
558:       if (carAlong > 0.2) {
559:         ball.velocity.addScaledVector(normal, carAlong * 0.72);
560:         strength = Math.max(strength, Math.min(2.2, carAlong / 24));
561:       }
562:       // nose/flip hits pop the ball
563:       const upward = Math.min(9.5, Math.abs(vn) * 0.16 + carSpeed * 0.07 + this.flipPower * 3.4);
564:       ball.velocity.y += upward;
565:       if (this.flipPower > 0.2) {
566:         ball.velocity.addScaledVector(this.forward, this.flipPower * 11);
567:         ball.velocity.y += this.flipPower * 4;
568:         strength += this.flipPower * 1.2;
569:       }
570: 
571:       // spin ball with a bit of side english
572:       ball.angularVelocity.add(new THREE.Vector3(
573:         (Math.random() - 0.5) * strength * 9,
574:         (Math.random() - 0.5) * strength * 9,
575:         (Math.random() - 0.5) * strength * 9
576:       ));
577: 
578:       // car loses a touch of speed
579:       this.velocity.multiplyScalar(0.978);
580:       if (strength > 0.15) {
581:         this.hitCooldown = 0.09;
582:         this.hooks.onBallHit?.(this, strength, ball);
583:       }
584:       this.lastImpact = strength;
585:     }
