588:   _syncVisuals(dt, steer) {
589:     this.root.position.copy(this.position);
590:     this.root.quaternion.copy(this.quaternion);
591: 
592:     // body lean / pitch
593:     const spd = Math.min(1, Math.abs(this.velocity.length()) / 45);
594:     const targetRoll = this.grounded ? -this.steerVisual * 0.075 * spd : 0;
595:     const targetPitch = this.grounded
596:       ? Math.max(-0.06, Math.min(0.06, (this.grounded ? -this.throttleVisual : 0) * 0.025 + (this.boosting ? 0.02 : 0)))
