import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
for (const [w, h, name] of [[390, 667, 'se'], [360, 640, 'small'], [844, 390, 'landscape']]) {
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => { console.log(name, 'PAGEERROR', e.message); errors.push(e.message); });
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
  await page.waitForTimeout(2200);
  const info = await page.evaluate(() => {
    const sels = ['#btn-play', '#btn-cinematic', '#mode-select', '#diff-select', '#menu-top'];
    const out = { vw: innerWidth, vh: innerHeight, scrollH: document.documentElement.scrollHeight };
    out.els = {};
    for (const s of sels) {
      const el = document.querySelector(s);
      if (!el) { out.els[s] = null; continue; }
      const r = el.getBoundingClientRect();
      out.els[s] = { top: +r.top.toFixed(0), bottom: +r.bottom.toFixed(0), left: +r.left.toFixed(0), right: +r.right.toFixed(0), visible: r.width > 0 && r.height > 0 };
    }
    return out;
  });
  console.log(name, JSON.stringify(info));
  await page.screenshot({ path: `/tmp/opencode/shots/menu-${name}.png` });
  await page.tap('#btn-play');
  await page.waitForTimeout(3500);
  const game = await page.evaluate(() => {
    const g = window.__RL3D__.game;
    const sels = ['#scoreboard', '#minimap-panel', '#hud-right', '#boost-hud', '#stick-zone', '#touch-actions'];
    const out = { state: g.state, vw: innerWidth, vh: innerHeight };
    out.els = {};
    for (const s of sels) {
      const el = document.querySelector(s);
      if (!el) { out.els[s] = null; continue; }
      const r = el.getBoundingClientRect();
      out.els[s] = { top: +r.top.toFixed(0), bottom: +r.bottom.toFixed(0), left: +r.left.toFixed(0), right: +r.right.toFixed(0), visible: r.width > 0 && r.height > 0 };
    }
    return out;
  });
  console.log(name, 'game', JSON.stringify(game));
  await page.screenshot({ path: `/tmp/opencode/shots/game-${name}.png` });
  console.log(name, 'errors', errors.length);
  await ctx.close();
}
