import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => { console.log('PAGEERROR', e.stack); errors.push(e.message); });
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.click('#btn-play');
await page.waitForTimeout(5000);

// isolate: put player center facing +x, ball far away
await page.evaluate(() => {
  const g = window.__RL3D__.game;
  for (const c of g.cars) if (c !== g.player) { c.reset(0, 0, 0); c.velocity.set(0,0,0); c.boost = 0; }
  g.player.reset(-20, 0, 0);
  g.ball.position.set(50, 8, 40);
  g.ball.velocity.set(0,0,0);
  g.ball.angularVelocity.set(0,0,0);
  g.cars.forEach(c => { c.isPlayer ? null : c.speed = 0; });
});

const samples = [];
await page.keyboard.down('KeyW');
for (let i = 0; i < 22; i++) {
  await page.waitForTimeout(100);
  samples.push(await page.evaluate(() => {
    const g = window.__RL3D__.game;
    return { t: +g.time.toFixed(2), x: +g.player.position.x.toFixed(1), speed: +g.player.speed.toFixed(1), boost: +g.player.boost.toFixed(0), grounded: g.player.grounded };
  }));
}
await page.keyboard.up('KeyW');
const maxSpeed = Math.max(...samples.map(s => s.speed));
console.log('drive samples', JSON.stringify(samples.slice(-6)), 'max', maxSpeed);

// boost
await page.evaluate(() => { const g = window.__RL3D__.game; g.player.reset(-35, 0, 0); g.player.boost = 100; });
await page.waitForTimeout(250);
await page.keyboard.down('KeyW');
await page.keyboard.down('ShiftLeft');
await page.waitForTimeout(1500);
const boosted = await page.evaluate(() => { const g = window.__RL3D__.game; return { speed: +g.player.speed.toFixed(1), boost: +g.player.boost.toFixed(0), x: +g.player.position.x.toFixed(1), boosting: g.player.boosting }; });
await page.keyboard.up('ShiftLeft');
await page.keyboard.up('KeyW');
console.log('boost 1.5s', JSON.stringify(boosted));

// jump / double jump
await page.evaluate(() => { const g = window.__RL3D__.game; g.player.reset(-10, 0, 0); g.ball.position.set(50, 8, 40); g.ball.velocity.set(0,0,0); });
await page.waitForTimeout(200);
await page.keyboard.press('Space');
await page.waitForTimeout(180);
const jump1 = await page.evaluate(() => { const p = window.__RL3D__.game.player; return { y: +p.position.y.toFixed(2), vy: +p.velocity.y.toFixed(1), jumps: p.jumps, grounded: p.grounded }; });
await page.waitForTimeout(220);
await page.keyboard.press('Space');
await page.waitForTimeout(160);
const jump2 = await page.evaluate(() => { const p = window.__RL3D__.game.player; return { y: +p.position.y.toFixed(2), vy: +p.velocity.y.toFixed(1), jumps: p.jumps, grounded: p.grounded, flip: +p.flipPower.toFixed(2) }; });
await page.waitForTimeout(1200);
const landed = await page.evaluate(() => { const p = window.__RL3D__.game.player; return { y: +p.position.y.toFixed(2), grounded: p.grounded, jumps: p.jumps }; });
console.log('jump', JSON.stringify({ jump1, jump2, landed }));

// ball collision: car hitting stationary ball
await page.evaluate(() => {
  const g = window.__RL3D__.game;
  g.player.reset(-8, 0, 0);
  g.ball.position.set(0, 1.8, 0);
  g.ball.velocity.set(0,0,0);
  g.ball.angularVelocity.set(0,0,0);
});
await page.waitForTimeout(250);
await page.keyboard.down('KeyW');
await page.waitForTimeout(1100);
await page.keyboard.up('KeyW');
const hit = await page.evaluate(() => { const g = window.__RL3D__.game; return { ballPos: g.ball.position.toArray().map(n=>+n.toFixed(1)), ballVel: g.ball.velocity.toArray().map(n=>+n.toFixed(1)), ballSpeed: +g.ball.velocity.length().toFixed(1), playerSpeed: +g.player.speed.toFixed(1) }; });
console.log('ball hit', JSON.stringify(hit));

console.log('errors', errors.length);
await browser.close();

