import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => { console.log('PAGEERROR', e.stack); errors.push(e.message); });
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.click('#btn-cinematic');
for (let i = 0; i < 8; i++) {
  await page.waitForTimeout(5000);
  const snap = await page.evaluate(() => {
    const g = window.__RL3D__.game;
    return {
      state: g.state, clock: +g.time.toFixed(1), score: g.score,
      ball: g.ball.position.toArray().map(n => +n.toFixed(1)),
      cars: g.cars.filter(c => c.active).map(c => ({ t: c.team, p: [c.position.x, c.position.z].map(n => +n.toFixed(1)), v: +c.speed.toFixed(1), b: +c.boost.toFixed(0), y: +c.position.y.toFixed(1) })),
    };
  });
  console.log((i + 1) * 5 + 's', JSON.stringify(snap));
  if (i === 2) await page.screenshot({ path: '/tmp/opencode/shots/ai-15s.png' });
  if (i === 5) await page.screenshot({ path: '/tmp/opencode/shots/ai-30s.png' });
}
await page.screenshot({ path: '/tmp/opencode/shots/ai-40s.png' });
console.log('errors', errors.length);
await browser.close();

