const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
for (const [w,h,name] of [[390,667,'se'],[360,640,'small'],[844,390,'land']]) {
  const ctx = await browser.newContext({ viewport:{width:w,height:h}, isMobile:true, hasTouch:true, deviceScaleFactor:2 });
  const page = await ctx.newPage();
  const errors=[]; page.on('pageerror',e=>{console.log(name,'ERR',e.message);errors.push(e.message)});
  await page.goto('http://127.0.0.1:3002/',{waitUntil:'load'});
  await page.waitForTimeout(1800);
  await page.tap('#btn-play');
  await page.waitForTimeout(4200);
  await page.evaluate(()=>{const g=window.__RL3D__.game; g.score={blue:3,orange:1}; g.stats={goals:2,shots:5,saves:1,boostUsed:0,topSpeed:214}; g.endMatch();});
  await page.waitForTimeout(900);
  const info = await page.evaluate(()=>{
    const el=document.querySelector('.results-wrap'); const r=el.getBoundingClientRect();
    const b=document.getElementById('btn-again').getBoundingClientRect();
    const m=document.getElementById('btn-menu').getBoundingClientRect();
    return {wrap:{t:+r.top.toFixed(0),b:+r.bottom.toFixed(0),h:+r.height.toFixed(0)},again:{t:+b.top.toFixed(0),b:+b.bottom.toFixed(0)},menu:{t:+m.top.toFixed(0),b:+m.bottom.toFixed(0)},vh:innerHeight,title:document.getElementById('result-title').textContent};
  });
  console.log(name,JSON.stringify(info));
  await page.screenshot({path:`/tmp/opencode/shots/results-${name}.png`});
  console.log(name,'errors',errors.length);
  await ctx.close();
}
await browser.close();

