205:     if (!car.grounded && car.jumps === 1 && car.velocity.y < 2.5 && distToBall < 9 && ball.position.y > car.position.y + 2.2 && Math.random() < this.diff.jump * dt * 4.5) {
206:       this.jumpQueued = true;
207:     }
208: 
209:     // air attitude: point roughly at the ball while airborne
210:     if (!car.grounded) {
211:       const dy = ball.position.y - car.position.y;
212:       throttle = THREE.MathUtils.clamp(-dy * 0.08, -1, 1);
