import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = []; page.on('pageerror', e => { console.log('ERR', e.message); errors.push(e.message); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1400);
await page.click('#mode-select [data-mode="1v1"]');
await page.click('#diff-select [data-diff="allstar"]');
await page.click('#btn-play');
for (let i = 0; i < 20; i++) {
  await page.waitForTimeout(1000);
  const s = await page.evaluate(() => {
    const g = window.__RL3D__.game;
    const ai = [...g.aiMap.values()][0];
    const c = ai?.car;
    return {
      st: g.state, clock: +g.time.toFixed(0), score: g.score,
      ball: g.ball.position.toArray().map(n => +n.toFixed(1)),
      car: c ? [c.position.x, c.position.z, c.yaw, c.speed, c.boost, c.grounded].map(n => typeof n === 'number' ? +n.toFixed(2) : n) : null,
      ai: ai ? { role: ai.role, target: [+ai.target.x.toFixed(1), +ai.target.z.toFixed(1)], rev: +ai.revTimer.toFixed(2), stuck: +ai.stuckTimer.toFixed(2), pad: ai.padTarget ? [ai.padTarget.x, ai.padTarget.z] : null } : null,
      lastCtrl: g.lastCtrl || null,
    };
  });
  console.log(i + 1, JSON.stringify(s));
}
console.log('errors', errors.length);
await browser.close();

