import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
const page = await ctx.newPage();
const errors = []; page.on('pageerror', e => { console.log('ERR', e.message); errors.push(e.message); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1800);
await page.tap('#btn-play');
await page.waitForTimeout(4500);
// reset player for a clean measurement
await page.evaluate(() => { const g = window.__RL3D__.game; g.player.reset(-30, 0, 0); for (const c of g.cars) if (c !== g.player) c.reset(40, 25, 0); g.ball.position.set(55, 5, 30); g.ball.velocity.set(0,0,0); });
const zone = await page.locator('#stick-zone').boundingBox();
const cx = zone.x + zone.width / 2, cy = zone.y + zone.height / 2;
await page.mouse.move(cx, cy);
await page.mouse.down();
await page.mouse.move(cx, cy - zone.height * 0.35, { steps: 5 });
await page.waitForTimeout(1200);
const drive = await page.evaluate(() => { const g = window.__RL3D__.game; return { speed: +g.player.speed.toFixed(1), x: +g.player.position.x.toFixed(1), touch: g.input.touch }; });
await page.screenshot({ path: '/tmp/opencode/shots/mobile-touch-drive.png' });
await page.mouse.up();
// jump button
const jump = await page.locator('#touch-jump').boundingBox();
await page.mouse.move(jump.x + jump.width / 2, jump.y + jump.height / 2);
await page.mouse.down();
await page.waitForTimeout(140);
const jumpState = await page.evaluate(() => { const p = window.__RL3D__.game.player; return { y: +p.position.y.toFixed(2), vy: +p.velocity.y.toFixed(1), jumps: p.jumps, grounded: p.grounded }; });
await page.mouse.up();
console.log('drive', JSON.stringify(drive));
console.log('jump', JSON.stringify(jumpState));
await page.waitForTimeout(1200);
console.log('landed', await page.evaluate(() => { const p = window.__RL3D__.game.player; return { y: +p.position.y.toFixed(2), grounded: p.grounded }; }));
console.log('errors', errors.length);
await browser.close();

