import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = []; page.on('pageerror', e => { console.log('ERR', e.message); errors.push(e.message); });
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.click('#btn-play');
await page.waitForTimeout(4800);
// force overtime
await page.evaluate(() => { const g = window.__RL3D__.game; g.score = { blue: 2, orange: 2 }; g.time = 0.05; });
await page.waitForTimeout(1500);
console.log('overtime start', await page.evaluate(() => { const g = window.__RL3D__.game; return { state: g.state, overtime: g.overtime, clockLabel: document.getElementById('clock-label').textContent, clock: document.getElementById('clock').textContent }; }));
await page.waitForTimeout(3500);
console.log('overtime playing', await page.evaluate(() => { const g = window.__RL3D__.game; return { state: g.state, overtime: g.overtime, overtimeElapsed: +g.overtimeElapsed.toFixed(1) }; }));
await page.evaluate(() => { const g = window.__RL3D__.game; g.forceGoal(1); });
